// Mapa de leitura da NBR 8160 — Missão 82 (Codex), validar_leitura.py exit 0. Paráfrase própria, sem texto da norma.
window.LEITURA = [{"id": "Prefácio", "tit": "Como usar esta edição", "pag": 1, "nivel": 1, "resumo": "Apresenta a revisão de 1999 e distingue anexos normativos e informativos.", "quadro": null, "pergunta": "Quais anexos são normativos?", "resposta": "B, C, D e G; A, E, F e H são informativos."}, {"id": "1", "tit": "Objetivo da norma", "pag": 1, "nivel": 1, "resumo": "Reúne critérios de projeto, execução, ensaio e manutenção do esgoto sanitário predial.", "quadro": "predio", "pergunta": "A norma trata só do tamanho dos tubos?", "resposta": "Não; também trata do desempenho, da execução, dos ensaios e da manutenção."}, {"id": "2", "tit": "Referências normativas", "pag": 2, "nivel": 1, "resumo": "Identifica documentos citados e recomenda verificar suas revisões ao firmar acordos.", "quadro": null, "pergunta": "Uma edição citada em 1999 deve ser tomada como atual automaticamente?", "resposta": "Não; o próprio item recomenda avaliar as edições mais recentes das referências."}, {"id": "3", "tit": "Definições", "pag": 2, "nivel": 1, "resumo": "Organiza os termos que evitam confundir aparelhos, desconectores e trechos da rede.", "quadro": "banheiro", "pergunta": "Ramal de descarga e ramal de esgoto são iguais?", "resposta": "Não: o primeiro recebe diretamente do aparelho; o segundo reúne contribuições dos ramais ou de um desconector."}, {"id": "3.1", "tit": "Altura do fecho hídrico", "pag": 2, "nivel": 3, "resumo": "É a profundidade de água que forma a barreira entre os lados do desconector.", "quadro": "fecho", "pergunta": "Altura do fecho é o tamanho externo do sifão?", "resposta": "Não; é uma medida da camada líquida na geometria definida do desconector."}, {"id": "3.2", "tit": "Aparelho sanitário", "pag": 2, "nivel": 3, "resumo": "É o ponto de uso de água ou recepção de dejetos e águas servidas ligado à instalação.", "quadro": "banheiro", "pergunta": "Um aparelho precisa ser uma bacia?", "resposta": "Não; lavatórios e outros aparelhos também fazem parte dessa categoria."}, {"id": "3.3", "tit": "Bacia sanitária", "pag": 2, "nivel": 3, "resumo": "É o aparelho destinado aos dejetos humanos.", "quadro": "banheiro", "pergunta": "Pode considerar a bacia como triturador de resíduos em geral?", "resposta": "Não; sua destinação sanitária não autoriza outros descartes."}, {"id": "3.4", "tit": "Barrilete de ventilação", "pag": 2, "nivel": 3, "resumo": "Reúne horizontalmente dois ou mais ventiladores e se comunica com a atmosfera.", "quadro": "terminal", "pergunta": "Barrilete é a mesma coisa que coluna vertical?", "resposta": "Não; aqui o barrilete é horizontal e reúne ventiladores."}, {"id": "3.5", "tit": "Caixa coletora", "pag": 2, "nivel": 3, "resumo": "Reúne efluentes cuja destinação exige elevação mecânica.", "quadro": null, "pergunta": "Para que serve a caixa antes das bombas de esgoto?", "resposta": "Para reunir os efluentes que precisarão ser elevados."}, {"id": "3.6", "tit": "Caixa de gordura", "pag": 2, "nivel": 3, "resumo": "Retém gorduras e óleos para remoção periódica antes que obstruam a rede.", "quadro": "gordura", "pergunta": "Reter gordura dispensa a limpeza da caixa?", "resposta": "Não; o material acumulado precisa ser removido periodicamente."}, {"id": "3.7", "tit": "Caixa de inspeção", "pag": 2, "nivel": 3, "resumo": "Dá acesso à rede e permite limpeza e operações de junção ou alteração do traçado.", "quadro": "inspecao", "pergunta": "A CI serve apenas para olhar o tubo?", "resposta": "Não; também permite limpeza, desobstrução e operações previstas no traçado."}, {"id": "3.8", "tit": "Caixa de passagem", "pag": 2, "nivel": 3, "resumo": "Permite reunir tubulações do subsistema de esgoto.", "quadro": "inspecao", "pergunta": "Caixa de passagem e caixa sifonada são sinônimos?", "resposta": "Não; a definição de passagem não lhe atribui fecho hídrico."}, {"id": "3.9", "tit": "Caixa sifonada", "pag": 2, "nivel": 3, "resumo": "Recebe efluentes da instalação secundária e incorpora um desconector.", "quadro": "banheiro", "pergunta": "O que distingue a caixa sifonada de uma caixa simples?", "resposta": "A presença do desconector com barreira hídrica."}, {"id": "3.10", "tit": "Coletor predial", "pag": 2, "nivel": 3, "resumo": "É o trecho final do sistema do prédio até a rede pública ou tratamento particular.", "quadro": "predio", "pergunta": "O coletor predial termina necessariamente em rede pública?", "resposta": "Não; pode terminar no sistema particular previsto."}, {"id": "3.11", "tit": "Coletor público", "pag": 2, "nivel": 3, "resumo": "É o trecho da rede coletiva que recebe os coletores dos prédios.", "quadro": null, "pergunta": "Coletor público fica restrito a um apartamento?", "resposta": "Não; pertence à rede coletora que recebe os coletores prediais."}, {"id": "3.12", "tit": "Coluna de ventilação", "pag": 2, "nivel": 3, "resumo": "É o ventilador vertical que atravessa pavimentos e se liga ao ar ou a outro elemento ventilador.", "quadro": "terminal", "pergunta": "Qual a diferença básica para o barrilete?", "resposta": "A coluna é vertical; o barrilete reúne ventiladores horizontalmente."}, {"id": "3.13", "tit": "Curva de raio longo", "pag": 2, "nivel": 3, "resumo": "É a conexão cujo raio médio atende à proporção mínima indicada com seu diâmetro interno.", "quadro": "sobre", "pergunta": "Qual proporção define o raio longo aqui?", "resposta": "Raio médio de curvatura pelo menos igual a duas vezes o diâmetro interno da peça."}, {"id": "3.14", "tit": "Desconector", "pag": 2, "nivel": 3, "resumo": "Bloqueia o caminho dos gases com uma barreira de água.", "quadro": "fecho", "pergunta": "O desconector é uma válvula mecânica obrigatoriamente?", "resposta": "Não; sua função aqui é cumprida pelo fecho hídrico."}, {"id": "3.15", "tit": "Diâmetro nominal", "pag": 2, "nivel": 3, "resumo": "É uma designação de tamanho usada para classificar e projetar tubulações.", "quadro": "banheiro", "pergunta": "DN é sempre o diâmetro externo medido com paquímetro?", "resposta": "Não; é designação nominal, aproximadamente associada ao diâmetro interno nesta definição."}, {"id": "3.16", "tit": "Dispositivo de inspeção", "pag": 2, "nivel": 3, "resumo": "É um acesso para examinar, limpar ou desobstruir a tubulação.", "quadro": "inspecao", "pergunta": "Todo acesso precisa ser uma grande caixa?", "resposta": "Não; a definição também contempla peça própria de inspeção."}, {"id": "3.17", "tit": "Dispositivos de tratamento", "pag": 2, "nivel": 3, "resumo": "São unidades que retiram sólidos e poluentes antes da destinação do efluente.", "quadro": null, "pergunta": "O tratamento serve só para reter gordura?", "resposta": "Não; visa também outros sólidos e poluentes do esgoto."}, {"id": "3.18", "tit": "Esgoto industrial", "pag": 2, "nivel": 3, "resumo": "Resulta dos processos industriais.", "quadro": null, "pergunta": "A norma dimensiona automaticamente qualquer efluente industrial?", "resposta": "Não; o objetivo e a ressalva inicial delimitam sua aplicação ao sanitário."}, {"id": "3.19", "tit": "Esgoto sanitário", "pag": 2, "nivel": 3, "resumo": "Resulta do uso da água para higiene.", "quadro": null, "pergunta": "A água de chuva é esgoto sanitário nesta definição?", "resposta": "Não; é preciso distinguir os sistemas, que devem ser separados."}, {"id": "3.20", "tit": "Facilidade de manutenção", "pag": 2, "nivel": 3, "resumo": "Expressa se é viável manter o sistema na prática.", "quadro": "inspecao", "pergunta": "Um acesso impossível de alcançar atende bem à manutenção?", "resposta": "Não; a manutenção deve ser viável, não apenas prevista no desenho."}, {"id": "3.21", "tit": "Fator de falha", "pag": 2, "nivel": 3, "resumo": "É a probabilidade de exceder a simultaneidade estimada dos aparelhos.", "quadro": null, "pergunta": "O fator de falha é o percentual de vazamentos da obra?", "resposta": "Não; está ligado à probabilidade de simultaneidade de uso."}, {"id": "3.22", "tit": "Fecho hídrico", "pag": 2, "nivel": 3, "resumo": "É a camada de água que impede a passagem dos gases no desconector.", "quadro": "fecho", "pergunta": "O que se perde quando o sifão seca?", "resposta": "A barreira hídrica contra os gases."}, {"id": "3.23", "tit": "Instalação primária", "pag": 2, "nivel": 3, "resumo": "É a parte da rede à qual os gases da rede pública ou do tratamento têm acesso.", "quadro": "fecho", "pergunta": "Primária quer dizer primeiro pavimento?", "resposta": "Não; o termo se refere ao acesso dos gases."}, {"id": "3.24", "tit": "Instalação secundária", "pag": 2, "nivel": 3, "resumo": "É a parte protegida do acesso dos gases da rede pública ou do tratamento.", "quadro": "fecho", "pergunta": "Secundária quer dizer tubulação menos importante?", "resposta": "Não; a distinção é a proteção em relação aos gases."}, {"id": "3.25", "tit": "Intervenientes", "pag": 2, "nivel": 3, "resumo": "São os participantes das fases de planejamento, projeto, produção, execução, uso e manutenção.", "quadro": null, "pergunta": "Apenas projetista e pedreiro são intervenientes?", "resposta": "Não; a cadeia inclui participantes das demais fases do empreendimento."}, {"id": "3.26", "tit": "Manual de uso e manutenção", "pag": 2, "nivel": 3, "resumo": "Reúne orientações de operação e procedimentos de manutenção do sistema.", "quadro": "inspecao", "pergunta": "Para que entregar o manual ao usuário?", "resposta": "Para orientar o uso e a manutenção adequados após a obra."}, {"id": "3.27", "tit": "Projeto como construído", "pag": 3, "nivel": 3, "resumo": "Registra o projeto incorporando as alterações realizadas na execução.", "quadro": "predio", "pergunta": "O projeto original sem correções é sempre o como construído?", "resposta": "Não; é preciso incorporar as alterações efetivas da obra."}, {"id": "3.28", "tit": "Programa de necessidades", "pag": 3, "nivel": 3, "resumo": "Reúne as informações básicas sobre as necessidades dos usuários.", "quadro": "predio", "pergunta": "De onde vêm as necessidades que o projeto precisa atender?", "resposta": "Do programa de necessidades, com as informações dos usuários finais."}, {"id": "3.29", "tit": "Ralo seco", "pag": 3, "nivel": 3, "resumo": "Recebe água por grelha sem incorporar proteção hídrica.", "quadro": "banheiro", "pergunta": "Um ralo seco sozinho bloqueia gases?", "resposta": "Não; ele não possui a proteção hídrica definida para o ralo sifonado."}, {"id": "3.30", "tit": "Ralo sifonado", "pag": 3, "nivel": 3, "resumo": "Recebe água por grelha e incorpora desconector.", "quadro": "banheiro", "pergunta": "O que o ralo sifonado tem que o seco não tem?", "resposta": "Desconector com proteção hídrica."}, {"id": "3.31", "tit": "Ramal de descarga", "pag": 3, "nivel": 3, "resumo": "Recebe diretamente os efluentes de um aparelho.", "quadro": "banheiro", "pergunta": "O tubo que sai diretamente do lavatório é que tipo de ramal?", "resposta": "Ramal de descarga."}, {"id": "3.32", "tit": "Ramal de esgoto", "pag": 3, "nivel": 3, "resumo": "Recebe contribuições dos ramais de descarga diretamente ou através de desconector.", "quadro": "banheiro", "pergunta": "O tubo que reúne os ramais dos aparelhos é chamado de quê?", "resposta": "Ramal de esgoto, observadas as características definidas do sistema."}, {"id": "3.33", "tit": "Ramal de ventilação", "pag": 3, "nivel": 3, "resumo": "Liga desconector ou ramal sanitário a uma coluna ou ventilador primário.", "quadro": "terminal", "pergunta": "Qual sua função de ligação na rede?", "resposta": "Interligar o trecho protegido à rede de ventilação."}, {"id": "3.34", "tit": "Rede pública de esgoto", "pag": 3, "nivel": 3, "resumo": "É a rede urbana coletora sob controle da autoridade pública.", "quadro": null, "pergunta": "A rede interna do condomínio é automaticamente rede pública?", "resposta": "Não; a definição envolve a rede urbana controlada pela autoridade pública."}, {"id": "3.35", "tit": "Requisitos de desempenho", "pag": 3, "nivel": 3, "resumo": "São as exigências sobre o comportamento final esperado do sistema.", "quadro": "predio", "pergunta": "Desempenho é somente o diâmetro calculado?", "resposta": "Não; diz respeito ao comportamento final que o sistema deve apresentar."}, {"id": "3.36", "tit": "Sifão", "pag": 3, "nivel": 3, "resumo": "É o desconector que recebe efluentes do sistema sanitário.", "quadro": "fecho", "pergunta": "Qual é a família funcional do sifão?", "resposta": "A dos desconectores."}, {"id": "3.37", "tit": "Sistema predial de esgoto", "pag": 3, "nivel": 3, "resumo": "Reúne coleta, transporte e controle dos gases do esgoto do prédio.", "quadro": "predio", "pergunta": "Os ventiladores também fazem parte do sistema?", "resposta": "Sim; controlar o destino dos gases integra sua função."}, {"id": "3.38", "tit": "Subsistema de coleta e transporte", "pag": 3, "nivel": 3, "resumo": "Capta o esgoto dos aparelhos e o conduz a um destino adequado.", "quadro": "predio", "pergunta": "Qual subsistema conduz os despejos do aparelho ao destino?", "resposta": "O de coleta e transporte."}, {"id": "3.39", "tit": "Subsistema de ventilação", "pag": 3, "nivel": 3, "resumo": "Conduz gases à atmosfera e evita sua chegada aos ambientes.", "quadro": "terminal", "pergunta": "A ventilação pode ter partes primária e secundária?", "resposta": "Sim; a definição admite essa divisão."}, {"id": "3.40", "tit": "Subcoletor", "pag": 3, "nivel": 3, "resumo": "Recebe efluentes de tubos de queda ou de ramais de esgoto.", "quadro": "predio", "pergunta": "O trecho que reúne duas quedas pode ser o quê?", "resposta": "Um subcoletor."}, {"id": "3.41", "tit": "Tubo de queda", "pag": 3, "nivel": 3, "resumo": "É a tubulação vertical que recebe contribuições sanitárias e as conduz entre níveis.", "quadro": "predio", "pergunta": "Qual característica geométrica identifica o TQ?", "resposta": "Sua disposição vertical, com as contribuições previstas na definição."}, {"id": "3.42", "tit": "Tubo ventilador", "pag": 3, "nivel": 3, "resumo": "Permite circulação de ar para proteger o fecho e encaminhar gases à atmosfera.", "quadro": "terminal", "pergunta": "Ventilador conduz esgoto como função normal?", "resposta": "Não; sua finalidade é a circulação do ar e proteção dos fechos."}, {"id": "3.43", "tit": "Ventilador de alívio", "pag": 3, "nivel": 3, "resumo": "Interliga a queda ou os ramais à coluna de ventilação.", "quadro": "sobre", "pergunta": "O alívio precisa ser um equipamento elétrico?", "resposta": "Não; é um tubo de ligação da rede de ventilação."}, {"id": "3.44", "tit": "Ventilador de circuito", "pag": 3, "nivel": 3, "resumo": "É a ligação secundária de um ramal que atende grupo sem ventilação individual.", "quadro": "banheiro", "pergunta": "Onde costuma aparecer o circuito na leitura das figuras?", "resposta": "Nos grupos de aparelhos, como as baterias de bacias da Figura 8."}, {"id": "3.45", "tit": "Tubulação de ventilação primária", "pag": 3, "nivel": 3, "resumo": "É o prolongamento do TQ acima da contribuição mais alta até a atmosfera.", "quadro": "terminal", "pergunta": "Por que o TQ continua acima do último ramal?", "resposta": "Para formar a tubulação de ventilação primária."}, {"id": "3.46", "tit": "Tubulação de ventilação secundária", "pag": 3, "nivel": 3, "resumo": "Reúne os tubos e as conexões que compõem a ventilação secundária.", "quadro": "terminal", "pergunta": "É uma única peça ou um conjunto?", "resposta": "Um conjunto de tubos e conexões com essa finalidade."}, {"id": "3.47", "tit": "Unidade autônoma", "pag": 3, "nivel": 3, "resumo": "É a parte de uso privativo da edificação identificada como unidade.", "quadro": "predio", "pergunta": "Um apartamento pode ser unidade autônoma?", "resposta": "Sim; é um exemplo compatível com a definição."}, {"id": "3.48", "tit": "Unidade de Hunter de contribuição", "pag": 3, "nivel": 3, "resumo": "É um fator numérico de contribuição associado ao uso habitual do aparelho.", "quadro": "banheiro", "pergunta": "UHC é um volume medido em litros?", "resposta": "Não; é um fator de contribuição, usado no método de dimensionamento por UHC."}, {"id": "3.49", "tit": "Ventilação primária", "pag": 3, "nivel": 3, "resumo": "Ocorre pelo núcleo de ar do TQ prolongado até a atmosfera.", "quadro": "terminal", "pergunta": "Primária e simples ausência de ventilador são iguais?", "resposta": "Não; há ventilação pelo núcleo do TQ prolongado."}, {"id": "3.50", "tit": "Ventilação secundária", "pag": 3, "nivel": 3, "resumo": "Ocorre por colunas, ramais ou barriletes que compõem a rede secundária.", "quadro": "terminal", "pergunta": "Qual caminho do ar caracteriza a secundária?", "resposta": "O interior dos seus ramais, colunas e barriletes ventiladores."}, {"id": "4", "tit": "Requisitos gerais", "pag": 3, "nivel": 1, "resumo": "Estabelece como o sistema deve funcionar antes de dimensionar suas partes.", "quadro": "predio", "pergunta": "Por onde começo antes de procurar um DN?", "resposta": "Pelos requisitos de funcionamento, pela concepção do sistema e pelas condições do prédio."}, {"id": "4.1", "tit": "Generalidades", "pag": 3, "nivel": 2, "resumo": "Relaciona a finalidade do sistema, o destino dos efluentes e a proteção dos ambientes.", "quadro": "predio", "pergunta": "A rede pode funcionar se descarregar rápido, mas deixar passar gases?", "resposta": "Não; escoamento e bloqueio dos gases são requisitos distintos que devem ser atendidos."}, {"id": "4.1.1", "tit": "Funções básicas", "pag": 3, "nivel": 3, "resumo": "O sistema deve levar os despejos do uso adequado dos aparelhos a um destino apropriado.", "quadro": "predio", "pergunta": "Qual é a função básica do sistema?", "resposta": "Coletar e conduzir os despejos sanitários a um destino adequado."}, {"id": "4.1.2", "tit": "Uso adequado dos aparelhos", "pag": 3, "nivel": 3, "resumo": "Delimita o uso dos aparelhos para evitar que recebam resíduos alheios ao esgoto.", "quadro": null, "pergunta": "Pode-se tratar a bacia como descarte de qualquer resíduo?", "resposta": "Não; o uso adequado pressupõe não lançar resíduos diferentes do esgoto."}, {"id": "4.1.3", "tit": "Desempenho do sistema", "pag": 3, "nivel": 3, "resumo": "Exige proteção da água, escoamento, contenção dos gases e condições de inspeção e manutenção.", "quadro": "predio", "pergunta": "Cite dois requisitos além de escoar água.", "resposta": "Evitar contaminação da água e impedir que os gases atinjam as áreas de utilização."}, {"id": "4.1.3.1", "tit": "Separação entre esgoto e chuva", "pag": 4, "nivel": 3, "resumo": "Impõe separação absoluta entre os sistemas sanitário e pluvial.", "quadro": "predio", "pergunta": "Pode unir esgoto e pluvial depois da última caixa?", "resposta": "Não; não deve haver ligação entre os dois sistemas."}, {"id": "4.1.4", "tit": "Destino final do coletor", "pag": 4, "nivel": 3, "resumo": "Define o encaminhamento para rede pública existente ou tratamento particular quando ela não existe.", "quadro": null, "pergunta": "Sem rede pública, onde lançar o efluente?", "resposta": "Em sistema particular de tratamento, não diretamente no ambiente sem solução adequada."}, {"id": "4.1.5", "tit": "Tratamento particular", "pag": 4, "nivel": 3, "resumo": "Vincula a concepção do tratamento particular à normalização brasileira pertinente.", "quadro": null, "pergunta": "A NBR 8160 sozinha dimensiona qualquer tratamento particular?", "resposta": "Não; é preciso aplicar a normalização pertinente ao tratamento escolhido."}, {"id": "4.1.6", "tit": "Triturador na pia", "pag": 4, "nivel": 3, "resumo": "Requer avaliar a adequação do triturador ao sistema segundo o fabricante.", "quadro": "gordura", "pergunta": "Instalar triturador dispensa avaliar a rede?", "resposta": "Não; é preciso verificar sua compatibilidade com o sistema e as recomendações do fabricante."}, {"id": "4.1.7", "tit": "Materiais e componentes", "pag": 4, "nivel": 3, "resumo": "Remete a seleção dos materiais às exigências do item 4.4.", "quadro": null, "pergunta": "Onde verificar os critérios de materiais?", "resposta": "No item 4.4, considerando o esgoto e as solicitações da instalação."}, {"id": "4.1.8", "tit": "Ruído nos ambientes", "pag": 4, "nivel": 3, "resumo": "Orienta evitar tubulação em ambientes de permanência prolongada ou atenuar o ruído quando isso não for possível.", "quadro": null, "pergunta": "Se um tubo passar no forro de um quarto, o que avaliar?", "resposta": "Evitar esse percurso e, se inviável, adotar medidas de atenuação da transmissão de ruído."}, {"id": "4.2", "tit": "Coleta e transporte", "pag": 4, "nivel": 2, "resumo": "Organiza os requisitos dos aparelhos, desconectores, ramais, quedas, coletores e recalque.", "quadro": "predio", "pergunta": "Quais partes principais este grupo reúne?", "resposta": "Aparelhos, desconectores, ramais, tubos de queda, coletores, dispositivos e recalque."}, {"id": "4.2.1", "tit": "Aparelhos sanitários", "pag": 4, "nivel": 3, "resumo": "Os aparelhos devem proteger a água potável e permitir uso confortável e manutenção.", "quadro": "banheiro", "pergunta": "O acesso para manutenção é exigência de projeto?", "resposta": "Sim; os aparelhos devem permitir acesso e manutenção adequados."}, {"id": "4.2.2", "tit": "Desconectores", "pag": 4, "nivel": 3, "resumo": "Estabelece a proteção dos aparelhos por desconectores e as condições dos conjuntos atendidos.", "quadro": "fecho", "pergunta": "Todo aparelho precisa de proteção contra gases?", "resposta": "Sim; a proteção pode ser individual ou atender um conjunto permitido da mesma unidade."}, {"id": "4.2.2.1", "tit": "Proteção de todos os aparelhos", "pag": 4, "nivel": 3, "resumo": "Exige desconector para os aparelhos, admitindo atendimento de conjunto da mesma unidade autônoma.", "quadro": "fecho", "pergunta": "Cada aparelho exige obrigatoriamente um sifão isolado?", "resposta": "Não; um desconector pode atender um conjunto permitido da mesma unidade autônoma."}, {"id": "4.2.2.3", "tit": "Aparelhos na caixa sifonada", "pag": 4, "nivel": 3, "resumo": "Admite reunir lavatório, bidê, banheira e chuveiro da mesma unidade, além de lavagem de piso nas condições indicadas.", "quadro": "banheiro", "pergunta": "A bacia entra na caixa sifonada comum do banheiro?", "resposta": "Não é o arranjo previsto aqui; a caixa pode reunir os aparelhos indicados, e a lavagem de piso exige grelha."}, {"id": "4.2.2.4", "tit": "Caixa de mictório", "pag": 4, "nivel": 3, "resumo": "A caixa que atende mictórios deve ser fechada com tampa cega e não receber outros aparelhos.", "quadro": "banheiro", "pergunta": "Um lavatório já sifonado pode entrar na caixa do mictório?", "resposta": "Não; nem a existência de sifão próprio cria essa permissão."}, {"id": "4.2.2.6", "tit": "Tanques e lavadoras sobrepostos", "pag": 4, "nivel": 3, "resumo": "Permite TQ exclusivo para a lavanderia com caixa sifonada especial no final.", "quadro": "predio", "pergunta": "É obrigatório usar essa solução para toda lavanderia?", "resposta": "O item permite essa solução; ela precisa ser compatibilizada com o projeto."}, {"id": "4.2.2.7", "tit": "Manutenção do fecho hídrico", "pag": 4, "nivel": 3, "resumo": "Exige preservar o fecho diante de evaporação, ambiente e pressões de uso.", "quadro": "fecho", "pergunta": "Ter 50 mm inicialmente basta para dispensar a verificação do fecho?", "resposta": "Não; sua manutenção sob as solicitações também precisa ser assegurada."}, {"id": "4.2.3", "tit": "Ramais de descarga e esgoto", "pag": 4, "nivel": 3, "resumo": "Define declividade, mudanças de direção e acesso dos ramais.", "quadro": "decl", "pergunta": "Como deve ser a declividade dos trechos horizontais?", "resposta": "Constante e capaz de proporcionar escoamento por gravidade."}, {"id": "4.2.3.2", "tit": "Mínimos recomendados dos ramais", "pag": 4, "nivel": 3, "resumo": "Recomenda declividades mínimas diferentes para tubos pequenos e tubos a partir de DN 100.", "quadro": "decl", "pergunta": "Quais mínimos o texto recomenda?", "resposta": "2% para DN até 75 e 1% para DN a partir de 100."}, {"id": "4.2.3.3", "tit": "Direção no horizontal", "pag": 5, "nivel": 3, "resumo": "Limita a 45° o ângulo central das peças de mudança de direção horizontal.", "quadro": "decl", "pergunta": "Pode-se usar diretamente um joelho de 90° numa mudança horizontal de ramal?", "resposta": "A regra horizontal exige peças de até 45°; não confundir com a transição horizontal–vertical."}, {"id": "4.2.3.4", "tit": "Transição horizontal e vertical", "pag": 5, "nivel": 3, "resumo": "Permite peças de até 90° nas mudanças entre horizontal e vertical.", "quadro": "decl", "pergunta": "A permissão de 90° vale indistintamente para todo desvio horizontal?", "resposta": "Não; ela se refere às mudanças horizontal–vertical e vice-versa."}, {"id": "4.2.3.5", "tit": "Ligação pela inspeção de curva", "pag": 5, "nivel": 3, "resumo": "Veda inserir ramal pela inspeção de joelho ou curva do ramal de descarga da bacia.", "quadro": "banheiro", "pergunta": "Posso aproveitar a tampa de inspeção da curva da bacia para ligar outro ramal?", "resposta": "Não; essa ligação é vedada."}, {"id": "4.2.4", "tit": "Tubos de queda", "pag": 5, "nivel": 3, "resumo": "Orienta alinhamento, desvios e prevenção de retorno de espuma nos tubos de queda.", "quadro": "sobre", "pergunta": "Um tubo de queda deve ter muitos desvios por conveniência do traçado?", "resposta": "Deve-se buscar um único alinhamento e justificar os desvios necessários."}, {"id": "4.2.4.2", "tit": "Controle de retorno de espuma", "pag": 5, "nivel": 3, "resumo": "Exige soluções contra espuma em edifícios de dois ou mais andares com aparelhos que usam detergentes.", "quadro": "sobre", "pergunta": "Cite uma solução contra o retorno de espuma.", "resposta": "Evitar ligações nas zonas de sobrepressão, usar desvio que atenue a pressão ou dispositivo antiespuma."}, {"id": "4.2.4.3", "tit": "Zonas de sobrepressão", "pag": 5, "nivel": 3, "resumo": "Identifica trechos críticos por múltiplos do diâmetro junto às bases e aos desvios.", "quadro": "sobre", "pergunta": "Quanto mede a zona de 40 diâmetros num TQ DN 100?", "resposta": "4,00 m; conferir na Figura 1 quais trechos correspondem a 40 D e a 10 D."}, {"id": "4.2.4.4", "tit": "Queda de pias e lava-louças", "pag": 5, "nivel": 3, "resumo": "Exige queda própria com ventilação primária conduzindo à caixa de gordura coletiva.", "quadro": "gordura", "pergunta": "No prédio, pias podem compartilhar livremente a queda dos banheiros?", "resposta": "Não; este item exige tubos especiais para pias e lava-louças, com destino à caixa coletiva."}, {"id": "4.2.5", "tit": "Subcoletores e coletor", "pag": 5, "nivel": 3, "resumo": "Define traçado, inspeção, transições e condições de escoamento dos coletores.", "quadro": "decl", "pergunta": "Como fazer um desvio de coletor?", "resposta": "Com peças de até 45° e meios de inspeção, mantendo as demais condições do traçado."}, {"id": "4.2.5.2", "tit": "Declividade dos coletores", "pag": 5, "nivel": 3, "resumo": "Exige declividade constante, remete aos mínimos gerais e fixa máximo de 5%.", "quadro": "decl", "pergunta": "Qual máximo se considera para subcoletores e coletor?", "resposta": "5%; a leitura da Tabela 7 não substitui os requisitos gerais do traçado."}, {"id": "4.2.5.3", "tit": "Obstáculos no coletor", "pag": 5, "nivel": 3, "resumo": "Impede dispositivos que prejudiquem o escoamento, mas permite válvula de retenção de esgoto.", "quadro": "inspecao", "pergunta": "Pode haver fundo de caixa abaixo do perfil natural do coletor?", "resposta": "Não se deve criar esse embaraço ao escoamento; a caixa deve respeitar o perfil."}, {"id": "4.2.5.4", "tit": "Mudança de diâmetro", "pag": 5, "nivel": 3, "resumo": "Vincula a variação de DN a inspeção ou peça própria de ampliação.", "quadro": "inspecao", "pergunta": "Pode mudar o DN do coletor com qualquer ligação improvisada?", "resposta": "Não; usar dispositivo de inspeção ou peça especial de ampliação."}, {"id": "4.2.5.5", "tit": "Junções aparentes e enterradas", "pag": 5, "nivel": 3, "resumo": "Distingue as junções com inspeção aparentes das interligações enterradas por caixas ou poços.", "quadro": "inspecao", "pergunta": "Uma interligação enterrada pode ser tratada como junção aparente?", "resposta": "Não; a norma prevê caixa de inspeção ou poço de visita para a enterrada."}, {"id": "Figura 1", "tit": "Localização das zonas de sobrepressão", "pag": 6, "nivel": 3, "resumo": "Mostra as zonas junto a bases e desvios para interpretar os múltiplos do diâmetro.", "quadro": "sobre", "pergunta": "Por que não copiar apenas o número 40 D?", "resposta": "Porque a figura e 4.2.4.3 distinguem trechos de 40 D e 10 D e suas posições."}, {"id": "4.2.6", "tit": "Dispositivos complementares", "pag": 6, "nivel": 3, "resumo": "Requer dispositivos estanques, ventilados e acessíveis à inspeção e manutenção.", "quadro": "inspecao", "pergunta": "Uma caixa coletiva pode ser inacessível porque fica enterrada?", "resposta": "Não; é preciso prever acesso, inspeção e demais características exigidas."}, {"id": "4.2.6.1", "tit": "Instalação das caixas de gordura", "pag": 6, "nivel": 3, "resumo": "Orienta instalação acessível e ventilada e proíbe caixas individuais nos pavimentos sobrepostos atendidos por quedas de cozinha.", "quadro": "gordura", "pergunta": "No prédio de dez pavimentos, pode haver uma caixa de gordura individual em cada andar?", "resposta": "Não nesse arranjo; pias e lava-louças sobrepostas devem seguir para caixas coletivas."}, {"id": "4.2.6.2", "tit": "Acessos e distâncias de inspeção", "pag": 6, "nivel": 3, "resumo": "Fixa distâncias de acesso e condições de localização dos dispositivos de inspeção.", "quadro": "inspecao", "pergunta": "Quais números devo localizar para a prova?", "resposta": "25 m entre inspeções, 15 m até a ligação pública, 10 m nos ramais indicados e CI a pelo menos 2 m dos TQs em prédio com mais de dois pavimentos."}, {"id": "4.2.7", "tit": "Recalque do esgoto", "pag": 7, "nivel": 3, "resumo": "Organiza coleta por gravidade e elevação mecânica quando os aparelhos estão abaixo do logradouro.", "quadro": null, "pergunta": "Abaixo da rua, basta uma bomba qualquer ligada ao ramal?", "resposta": "Não; há caixa coletora, condições de inspeção, bombas apropriadas, controle e proteção contra refluxo."}, {"id": "4.3", "tit": "Subsistema de ventilação", "pag": 7, "nivel": 2, "resumo": "Define concepção, ligações e terminais que preservam os fechos e conduzem gases à atmosfera.", "quadro": "terminal", "pergunta": "Ventilar é apenas levar um tubo até o telhado?", "resposta": "Não; também envolve geometria, proteção dos desconectores e ligações corretas."}, {"id": "4.3.1", "tit": "Duas concepções de ventilação", "pag": 7, "nivel": 3, "resumo": "Admite sistema apenas com ventilação primária ou com primária e secundária.", "quadro": "terminal", "pergunta": "A secundária é a única concepção admitida?", "resposta": "Não; a solução só com primária é admitida, mas sua suficiência deve ser verificada."}, {"id": "4.3.2", "tit": "Verificação da primária", "pag": 7, "nivel": 3, "resumo": "Exige verificar pelo Anexo C a suficiência da solução apenas com ventilação primária.", "quadro": "fecho", "pergunta": "Posso dispensar a secundária só por achar o prédio pequeno?", "resposta": "Não; a suficiência da primária deve ser verificada pelo modelo do Anexo C."}, {"id": "4.3.3", "tit": "Primária insuficiente", "pag": 7, "nivel": 3, "resumo": "Permite rever a geometria e verificar novamente ou acrescentar ventilação secundária.", "quadro": "terminal", "pergunta": "O que fazer quando a primária não atende?", "resposta": "Rever a geometria e repetir a verificação, ou prever ventilação secundária."}, {"id": "4.3.4", "tit": "Formas de ventilação secundária", "pag": 7, "nivel": 3, "resumo": "Apresenta ramais e colunas ou dispositivos de admissão de ar devidamente posicionados.", "quadro": "terminal", "pergunta": "A norma cita válvulas de admissão de ar?", "resposta": "Sim; elas aparecem como alternativa da ventilação secundária, com posicionamento adequado."}, {"id": "4.3.5", "tit": "Extremidade acima da cobertura", "pag": 7, "nivel": 3, "resumo": "Exige posicionar a abertura de modo a impedir entrada das águas pluviais da cobertura.", "quadro": "terminal", "pergunta": "Pode terminar a ventilação na própria superfície da laje?", "resposta": "Não; a extremidade deve ficar acima da cobertura nas condições prescritas."}, {"id": "4.3.6", "tit": "Alturas e afastamentos do terminal", "pag": 7, "nivel": 3, "resumo": "Combina afastamento de vãos, altura acima da cobertura e proteção do terminal.", "quadro": "terminal", "pergunta": "Quais alturas devo lembrar?", "resposta": "0,30 m na cobertura sem outro uso, 2,00 m se utilizável e, a menos de 4 m de vão, pelo menos 1 m acima da verga."}, {"id": "Figura 2", "tit": "Exemplos de ventilação secundária", "pag": 8, "nivel": 3, "resumo": "Ilustra alternativas com admissão de ar e com ramais e colunas ventiladoras.", "quadro": "terminal", "pergunta": "Em que página começa a Figura 2?", "resposta": "Na página 8; ela continua e recebe a legenda geral na 9."}, {"id": "Figura 3", "tit": "Terminal acima da cobertura", "pag": 10, "nivel": 3, "resumo": "Ilustra altura da abertura da ventilação conforme a cobertura e os vãos próximos.", "quadro": "terminal", "pergunta": "Se a janela estiver a menos de 4 m, basta subir 0,30 m da laje?", "resposta": "Não; cumprir também pelo menos 1 m acima da verga, sem deixar de atender à altura da cobertura."}, {"id": "4.3.7", "tit": "Concepção da secundária", "pag": 10, "nivel": 3, "resumo": "Encaminha a leitura para as condições detalhadas das ligações e dos trechos ventiladores.", "quadro": "terminal", "pergunta": "Onde procurar as regras da ventilação secundária além do desenho?", "resposta": "Nos itens seguintes da seção 4.3, sem usar a figura como substituta das condições escritas."}, {"id": "4.3.8", "tit": "Esgoto na ventilação", "pag": 10, "nivel": 3, "resumo": "Impede entrada de esgoto na ventilação, ressalvados os trechos previstos no item de ligação.", "quadro": "terminal", "pergunta": "Posso projetar a coluna ventiladora para receber esgoto normalmente?", "resposta": "Não; a exceção indicada deve ser lida junto de 4.3.16 b)."}, {"id": "4.3.9", "tit": "Prumadas e curvas de ventilação", "pag": 10, "nivel": 3, "resumo": "Orienta prumada vertical e limita as curvas, com aclive mínimo nos desvios.", "quadro": "terminal", "pergunta": "Qual aclive é previsto nos desvios da ventilação?", "resposta": "Pelo menos 1%, com curvas de ângulo central não superior a 90°."}, {"id": "4.3.10", "tit": "Ventilar o desvio do TQ", "pag": 10, "nivel": 3, "resumo": "Dá alternativas de ventilação quando o desvio excede 45° em relação à vertical.", "quadro": "sobre", "pergunta": "Um desvio maior que 45° pode ser ignorado na ventilação?", "resposta": "Não; tratar como dois tubos independentes ou acompanhar o desvio com coluna e alívios acima e abaixo."}, {"id": "4.3.11", "tit": "Ventilação em um pavimento", "pag": 10, "nivel": 3, "resumo": "Exige ao menos um tubo ventilador e ligação dos desconectores a elemento ventilado respeitando a Tabela 1.", "quadro": "terminal", "pergunta": "Qual tabela limita a distância do desconector ao ventilador?", "resposta": "Tabela 1; por exemplo, DN 50 corresponde a 1,20 m."}, {"id": "4.3.12", "tit": "Dispensa de prolongar outros TQs", "pag": 10, "nivel": 3, "resumo": "Admite dispensa condicionada quando já há ventilador primário DN 100 no TQ mais afastado.", "quadro": "terminal", "pergunta": "Quais limites participam da dispensa?", "resposta": "Comprimento até um quarto da altura do prédio, até 36 UHC e coluna ventiladora na condição exigida, além do primário DN 100."}, {"id": "4.3.13", "tit": "Aclive de toda ventilação", "pag": 10, "nivel": 3, "resumo": "Exige aclive para que líquido eventual retorne por gravidade ao ramal de origem.", "quadro": "decl", "pergunta": "Qual é o aclive mínimo da tubulação ventiladora?", "resposta": "1%, sem esquecer a alternativa particular de 2% em 4.3.16 b)."}, {"id": "4.3.14", "tit": "Coluna de ventilação", "pag": 10, "nivel": 3, "resumo": "Exige DN uniforme e define as ligações da base e do topo da coluna.", "quadro": "terminal", "pergunta": "A ligação superior pode ficar abaixo do transbordamento do aparelho mais alto?", "resposta": "Não; se ligada ao primário, deve ficar pelo menos 0,15 m acima do nível indicado."}, {"id": "Figura 4", "tit": "Ventilação no desvio de TQ", "pag": 11, "nivel": 3, "resumo": "Ilustra alternativas de ventilação para o desvio superior a 45° da vertical.", "quadro": "sobre", "pergunta": "Quais são as duas alternativas de 4.3.10?", "resposta": "Considerar duas quedas independentes ou acompanhar o desvio com coluna e ventiladores de alívio."}, {"id": "Tabela 1", "tit": "Distância do desconector ao ventilador", "pag": 11, "nivel": 3, "resumo": "Relaciona DN do ramal de descarga e distância máxima ao tubo ventilador.", "quadro": "terminal", "pergunta": "Qual distância máxima para DN 100?", "resposta": "2,40 m; para DN 40, 50 e 75, os limites são 1,00, 1,20 e 1,80 m."}, {"id": "Tabela 2", "tit": "Colunas e barriletes de ventilação", "pag": 12, "nivel": 3, "resumo": "Cruza DN e UHC do trecho sanitário com comprimento permitido para cada DN ventilador.", "quadro": "terminal", "pergunta": "Para TQ 100 e 290 UHC, qual linha usar?", "resposta": "A linha 100/320; escolher a menor carga tabelada suficiente, e depois conferir o comprimento."}, {"id": "4.3.15", "tit": "Barrilete de ventilação", "pag": 13, "nivel": 3, "resumo": "Permite reunir ventiladores em barrilete quando não convém prolongar todos até acima da cobertura.", "quadro": "terminal", "pergunta": "Qual aclive mínimo do barrilete?", "resposta": "1%, até o trecho prolongado e respeitando as condições do terminal."}, {"id": "4.3.16", "tit": "Ligações da ventilação", "pag": 13, "nivel": 3, "resumo": "Diferencia conexão vertical e horizontal e prevê alternativa quando falta espaço para elevação.", "quadro": "terminal", "pergunta": "Sem espaço vertical, basta reduzir qualquer ângulo e deixar o trecho plano?", "resposta": "Não; a alternativa exige junção de 45° e trecho inicial com aclive mínimo de 2%."}, {"id": "4.3.17", "tit": "Ventilar abaixo da bacia", "pag": 13, "nivel": 3, "resumo": "Prevê ventilação do TQ imediatamente abaixo da bacia quando não se pode ventilar seu ramal.", "quadro": "banheiro", "pergunta": "Onde ventilar se o ramal da bacia não puder ser ventilado?", "resposta": "No TQ imediatamente abaixo da ligação, observando a distância aplicável."}, {"id": "4.3.18", "tit": "Dispensa do ramal da bacia", "pag": 13, "nivel": 3, "resumo": "Dispensa ventilação do ramal exclusivo curto somente com contribuições ventiladas nas condições indicadas.", "quadro": "banheiro", "pergunta": "Basta o ramal da bacia ter menos de 2,40 m para dispensar ventilação?", "resposta": "Não; o TQ também deve receber ramais ventilados logo abaixo, no mesmo pavimento."}, {"id": "4.3.19", "tit": "Bacias em bateria", "pag": 13, "nivel": 3, "resumo": "Prevê ventilador de circuito e ventiladores suplementares conforme o grupo de bacias.", "quadro": "banheiro", "pergunta": "Onde se liga o circuito e a cada quantas bacias se prevê suplementar?", "resposta": "Entre a última e a penúltima bacia; suplementar a cada grupo de no máximo oito."}, {"id": "4.3.20", "tit": "Circuito em baterias de bacias", "pag": 13, "nivel": 3, "resumo": "Repete na edição fornecida as condições de circuito e suplementação para baterias.", "quadro": "banheiro", "pergunta": "O texto repetido muda o limite de oito bacias?", "resposta": "Não; conferir junto da Figura 8 e das demais condições, sem inventar uma exceção pela repetição."}, {"id": "4.3.21", "tit": "Suplementar no início da bateria", "pag": 13, "nivel": 3, "resumo": "Exige ligação suplementar no início do ramal quando há mais de três bacias e contribuições superiores.", "quadro": "banheiro", "pergunta": "Quando aparece o suplementar entre o TQ e a primeira bacia?", "resposta": "Quando o ramal atende mais de três bacias e há aparelhos em andares superiores descarregando no TQ."}, {"id": "Figura 5", "tit": "Ligação do ramal ventilador", "pag": 13, "nivel": 3, "resumo": "Mostra a geometria de inserção e elevação do ramal de ventilação.", "quadro": "terminal", "pergunta": "Qual distância mínima entre aparelho e inserção do ventilador?", "resposta": "Duas vezes o DN do ramal de descarga, nas condições de 4.3.16."}, {"id": "Figura 6", "tit": "Ventilação abaixo da ligação da bacia", "pag": 14, "nivel": 3, "resumo": "Ilustra a solução quando não é possível ventilar o ramal de descarga da bacia.", "quadro": "banheiro", "pergunta": "Onde aparece o ventilador nessa alternativa?", "resposta": "Imediatamente abaixo da ligação do ramal da bacia ao TQ, conforme 4.3.17."}, {"id": "Figura 7", "tit": "Dispensa condicionada do ramal da bacia", "pag": 14, "nivel": 3, "resumo": "Ilustra a dispensa de ventilação do ramal exclusivo com contribuição ventilada logo abaixo.", "quadro": "banheiro", "pergunta": "Qual limite de distância participa da dispensa?", "resposta": "2,40 m, junto das demais condições do item 4.3.18."}, {"id": "Figura 8", "tit": "Ventilação em circuito", "pag": 15, "nivel": 3, "resumo": "Ilustra circuito e suplementação de ventilação em bateria de bacias.", "quadro": "banheiro", "pergunta": "Entre quais bacias se liga o circuito?", "resposta": "Entre a última e a penúltima; conferir a suplementação e as condições de 4.3.19 a 4.3.21."}, {"id": "4.4", "tit": "Materiais", "pag": 15, "nivel": 2, "resumo": "Orienta selecionar materiais pelas características do esgoto e das solicitações.", "quadro": null, "pergunta": "Qual é o critério além do preço do tubo?", "resposta": "Temperatura, ações químicas e físicas, esforços e normalização aplicável."}, {"id": "4.4.1", "tit": "Solicitações dos materiais", "pag": 15, "nivel": 3, "resumo": "Relaciona o material às condições reais de exposição e serviço.", "quadro": null, "pergunta": "Só verificar o DN garante material adequado?", "resposta": "Não; também é preciso avaliar o tipo de esgoto, temperatura e solicitações."}, {"id": "4.4.2", "tit": "Normalização dos componentes", "pag": 15, "nivel": 3, "resumo": "Restringe o uso a materiais normalizados, com a ressalva indicada para os ainda não normalizados pela ABNT.", "quadro": null, "pergunta": "Um material sem norma ABNT é sempre proibido?", "resposta": "A nota admite norma do país de origem quando ainda não houver normalização no âmbito da ABNT."}, {"id": "4.5", "tit": "Documentos do projeto", "pag": 15, "nivel": 2, "resumo": "Relaciona plantas, esquema vertical, detalhes, memorial, especificações, quantidades e orçamento.", "quadro": "predio", "pergunta": "Uma planta de um banheiro basta como projeto completo?", "resposta": "Não; são necessários os documentos do conjunto, inclusive pavimento inferior com cotas e esquema das interligações."}, {"id": "5", "tit": "Dimensionamento", "pag": 15, "nivel": 1, "resumo": "Apresenta os critérios de dimensionamento da coleta, do transporte e da ventilação.", "quadro": "predio", "pergunta": "Onde estão os critérios numéricos principais?", "resposta": "Na seção 5 e nas tabelas correspondentes, ou nos anexos do método hidráulico."}, {"id": "5.1", "tit": "Coleta e transporte: métodos", "pag": 15, "nivel": 2, "resumo": "Permite método hidráulico ou UHC mantendo os mínimos dos ramais de descarga.", "quadro": "predio", "pergunta": "Escolher o método hidráulico elimina os mínimos dos aparelhos?", "resposta": "Não; os mínimos da Tabela 3 permanecem, observadas suas notas condicionais."}, {"id": "5.1.1", "tit": "Dimensionar desconectores", "pag": 15, "nivel": 3, "resumo": "Define fecho, saída e critérios das caixas sifonadas comuns e especiais.", "quadro": "fecho", "pergunta": "A caixa comum e a especial da lavanderia são a mesma peça normativa?", "resposta": "Não; têm critérios próprios nos subitens seguintes."}, {"id": "5.1.1.1", "tit": "Fecho e saída do desconector", "pag": 15, "nivel": 3, "resumo": "Exige fecho hídrico mínimo e saída compatível com o ramal de descarga conectado.", "quadro": "fecho", "pergunta": "Qual fecho mínimo e como comparar a saída?", "resposta": "Fecho de pelo menos 0,05 m; saída de diâmetro igual ou superior ao ramal conectado."}, {"id": "5.1.1.2", "tit": "Caixas sifonadas comuns", "pag": 16, "nivel": 3, "resumo": "Relaciona o DN da caixa às UHC dos aparelhos atendidos.", "quadro": "banheiro", "pergunta": "Quais patamares de UHC correspondem às caixas?", "resposta": "DN 100 até 6 UHC, DN 125 até 10 e DN 150 até 15; não confundir caixa com ramal de saída."}, {"id": "5.1.1.3", "tit": "Caixa sifonada especial", "pag": 16, "nivel": 3, "resumo": "Define a geometria e o fechamento da caixa especial prevista para quedas de lavanderia.", "quadro": "predio", "pergunta": "Quais números caracterizam a CS especial?", "resposta": "Fecho 0,20 m, diâmetro interno ou círculo inscrito 0,30 m e saída DN 75, com tampa hermética removível."}, {"id": "5.1.2", "tit": "Dimensionar os ramais", "pag": 16, "nivel": 3, "resumo": "Direciona os aparelhos e os ramais às Tabelas 3, 4 e 5.", "quadro": "banheiro", "pergunta": "Qual tabela uso para o ramal de descarga de um aparelho conhecido?", "resposta": "Tabela 3; a soma dos ramais de esgoto é tratada na Tabela 5."}, {"id": "5.1.2.1", "tit": "Mínimos dos ramais de descarga", "pag": 16, "nivel": 3, "resumo": "Exige os DN mínimos dos aparelhos relacionados na Tabela 3.", "quadro": "banheiro", "pergunta": "Qual o mínimo da descarga da pia de cozinha residencial?", "resposta": "DN 50; não adotar DN 40 só porque a pia tem 3 UHC."}, {"id": "5.1.2.2", "tit": "Aparelhos não listados", "pag": 16, "nivel": 3, "resumo": "Encaminha a estimativa das UHC de aparelho ausente da Tabela 3 para a Tabela 4.", "quadro": "banheiro", "pergunta": "Se o aparelho não está na Tabela 3, posso atribuir zero UHC?", "resposta": "Não; estimar a contribuição e usar a Tabela 4 conforme o item."}, {"id": "5.1.2.3", "tit": "Capacidade dos ramais de esgoto", "pag": 16, "nivel": 3, "resumo": "Usa a Tabela 5 para a carga somada no ramal de esgoto.", "quadro": "banheiro", "pergunta": "Qual DN atende 7 UHC, sem outro mínimo maior?", "resposta": "DN 75, pois DN 50 atende somente até 6 UHC."}, {"id": "Tabela 3", "tit": "Aparelhos: UHC e ramais de descarga", "pag": 16, "nivel": 3, "resumo": "Lista as contribuições e os DN mínimos dos aparelhos sanitários.", "quadro": "banheiro", "pergunta": "Quais valores de bacia, lavatório e chuveiro residencial?", "resposta": "Bacia 6/DN 100, lavatório 1/DN 40 e chuveiro 2/DN 40, observadas as notas da tabela."}, {"id": "Tabela 4", "tit": "Aparelhos não relacionados", "pag": 17, "nivel": 3, "resumo": "Associa a contribuição estimada ao DN do ramal de descarga para o caso não listado.", "quadro": "banheiro", "pergunta": "Quais UHC correspondem a DN 40, 50, 75 e 100?", "resposta": "2, 3, 5 e 6 UHC, respectivamente, no contexto de 5.1.2.2."}, {"id": "Tabela 5", "tit": "Ramais de esgoto", "pag": 17, "nivel": 3, "resumo": "Fornece a capacidade máxima em UHC do ramal de esgoto.", "quadro": "banheiro", "pergunta": "Quais limites de DN 40, 50, 75 e 100?", "resposta": "3, 6, 20 e 160 UHC; preservar os demais mínimos aplicáveis."}, {"id": "5.1.3", "tit": "Dimensionar os TQs", "pag": 17, "nivel": 3, "resumo": "Aplica a carga total e os critérios dos desvios aos tubos de queda.", "quadro": "predio", "pergunta": "Qual tabela dimensiona TQ pelo método UHC?", "resposta": "Tabela 6, escolhendo a coluna da quantidade de pavimentos."}, {"id": "5.1.3.1", "tit": "TQ pela soma de UHC", "pag": 17, "nivel": 3, "resumo": "Permite dimensionar o TQ com as capacidades da Tabela 6.", "quadro": "predio", "pergunta": "No prédio de dez pavimentos, 501 UHC cabem em DN 100?", "resposta": "Não; nessa coluna, DN 100 admite até 500 UHC e o próximo patamar é DN 150."}, {"id": "5.1.3.2", "tit": "TQ com desvios", "pag": 17, "nivel": 3, "resumo": "Distingue desvios até 45° dos maiores e preserva o DN abaixo do trecho horizontal.", "quadro": "sobre", "pergunta": "Acima de 45°, posso usar só a Tabela 6 no conjunto?", "resposta": "Não; o horizontal usa a Tabela 7 e a parte abaixo não pode ter DN menor que ele."}, {"id": "5.1.4", "tit": "Dimensionar coletores", "pag": 17, "nivel": 3, "resumo": "Relaciona a carga dos coletores à Tabela 7 e à regra residencial dos banheiros.", "quadro": "predio", "pergunta": "A carga do TQ e a do coletor residencial são necessariamente iguais?", "resposta": "Não; a redução específica dos banheiros residenciais só se aplica aos coletores e subcoletores."}, {"id": "5.1.4.1", "tit": "Tabela e mínimo do coletor", "pag": 17, "nivel": 3, "resumo": "Permite usar a Tabela 7 e exige coletor predial de no mínimo DN 100.", "quadro": "decl", "pergunta": "1288 UHC a 1% exigem qual DN tabelado?", "resposta": "DN 200, cuja capacidade nessa declividade é 1600 UHC."}, {"id": "5.1.4.2", "tit": "Redução residencial", "pag": 17, "nivel": 3, "resumo": "Considera apenas o aparelho de maior descarga de cada banheiro nos coletores residenciais.", "quadro": "predio", "pergunta": "No nosso cenário literal, como chegar às 1288 UHC?", "resposta": "Três bacias: 18, cozinha: 8, lavanderia: 6; (18 + 8 + 6) × 40 + 8 da guarita = 1288, como premissa ainda não adotada."}, {"id": "Tabela 6", "tit": "Capacidade dos tubos de queda", "pag": 18, "nivel": 3, "resumo": "Distingue as capacidades dos TQs para prédios até três pavimentos e com mais de três.", "quadro": "predio", "pergunta": "Qual coluna usar no nosso prédio de dez pavimentos?", "resposta": "A de mais de três; DN 75 atende até 70 UHC e DN 100 até 500 UHC."}, {"id": "Tabela 7", "tit": "Subcoletores e coletor predial", "pag": 18, "nivel": 3, "resumo": "Relaciona a capacidade em UHC do coletor ao DN e à declividade tabelada.", "quadro": "decl", "pergunta": "DN 100 existe na coluna de 0,5%?", "resposta": "Não; as células de DN 100 e 150 nessa coluna não são aplicáveis, e os critérios gerais do traçado também devem ser lidos."}, {"id": "5.1.5", "tit": "Dimensionar dispositivos", "pag": 18, "nivel": 3, "resumo": "Reúne os critérios das caixas de gordura, passagem e inspeção.", "quadro": "inspecao", "pergunta": "O mesmo tamanho serve para todas as caixas?", "resposta": "Não; função, carga e geometria variam por tipo."}, {"id": "5.1.5.1", "tit": "Caixas de gordura", "pag": 18, "nivel": 3, "resumo": "Define seleção e dimensões das caixas de gordura pela aplicação.", "quadro": "gordura", "pergunta": "Que dados decidem a seleção da caixa?", "resposta": "Quantidade e tipo de cozinhas e, para CGE, pessoas servidas no maior afluxo."}, {"id": "5.1.5.1.1", "tit": "Selecionar a caixa de gordura", "pag": 18, "nivel": 3, "resumo": "Distribui as aplicações entre CGP, CGS, CGD e CGE.", "quadro": "gordura", "pergunta": "Que caixa atende dez cozinhas residenciais de um shaft?", "resposta": "CGD; para mais de doze ou usos especiais indicados, prever CGE."}, {"id": "5.1.5.1.2", "tit": "Câmaras da caixa de gordura", "pag": 18, "nivel": 3, "resumo": "Exige câmaras receptora e vertedoura separadas por septo não removível.", "quadro": "gordura", "pergunta": "A caixa pode ser um recipiente sem separação interna?", "resposta": "Não; deve ter as duas câmaras com septo fixo."}, {"id": "5.1.5.1.3", "tit": "Tipos e dimensões da gordura", "pag": 18, "nivel": 3, "resumo": "Especifica dimensões, saídas e volumes dos quatro tipos de caixa.", "quadro": "gordura", "pergunta": "Qual volume da CGE para cem pessoas no maior afluxo?", "resposta": "V = 2 × 100 + 20 = 220 L; N é de pessoas, não de cozinhas."}, {"id": "5.1.5.2", "tit": "Caixas de passagem", "pag": 19, "nivel": 3, "resumo": "Define dimensões mínimas, tampa e saída da caixa de passagem.", "quadro": "inspecao", "pergunta": "Qual mínimo da saída e da base?", "resposta": "Saída DN 50 ou maior pelo dimensionamento; diâmetro ou círculo inscrito mínimo de 0,15 m."}, {"id": "5.1.5.3", "tit": "Caixas de inspeção e poços", "pag": 19, "nivel": 3, "resumo": "Diferencia CI e PV e fixa seus requisitos de acesso e geometria.", "quadro": "inspecao", "pergunta": "Quando deixar de tratar o dispositivo como CI?", "resposta": "Acima de 1 m de profundidade; a CI tem lado ou diâmetro interno mínimo de 0,60 m e o PV, 1,10 m, com demais condições do item."}, {"id": "5.1.6", "tit": "Dimensionar o recalque", "pag": 19, "nivel": 3, "resumo": "Considera vazão, detenção e frequência de partidas na instalação de elevação.", "quadro": null, "pergunta": "Dimensionar apenas o diâmetro da bomba encerra a análise?", "resposta": "Não; considerar capacidade, detenção e intervalo entre partidas."}, {"id": "5.1.6.1", "tit": "Aspectos do recalque", "pag": 19, "nivel": 3, "resumo": "Relaciona a bomba às contribuições simultâneas e aos tempos da caixa.", "quadro": null, "pergunta": "Qual vazão importa para a capacidade da bomba?", "resposta": "A máxima provável dos aparelhos e dispositivos que possam funcionar simultaneamente, nas condições do projeto."}, {"id": "5.1.6.2", "tit": "Capacidade da caixa coletora", "pag": 19, "nivel": 3, "resumo": "Equilibra volume suficiente para as partidas e volume que evite estado séptico.", "quadro": null, "pergunta": "Quanto maior a caixa, melhor sempre?", "resposta": "Não; volume excessivo pode aumentar a detenção e favorecer estado séptico."}, {"id": "5.1.6.3", "tit": "Recalque com bacias", "pag": 20, "nivel": 3, "resumo": "Exige condições próprias para caixa e bombas que recebem efluentes fecais.", "quadro": null, "pergunta": "Quais mínimos lembrar para o caso com bacias?", "resposta": "Profundidade 0,90 m, dois grupos motobomba alternados, passagem de esfera de 60 mm e recalque DN 75, com ventilação e demais condições."}, {"id": "5.1.6.4", "tit": "Recalque sem bacias", "pag": 20, "nivel": 3, "resumo": "Define mínimos diferentes quando não há efluente de bacia sanitária.", "quadro": null, "pergunta": "Quais números mudam sem bacias?", "resposta": "Profundidade mínima de 0,60 m, passagem de esfera de 18 mm e recalque mínimo DN 40."}, {"id": "5.1.6.5", "tit": "Tubulações de sucção", "pag": 20, "nivel": 3, "resumo": "Prevê uma sucção por bomba com diâmetro uniforme compatível com o recalque.", "quadro": null, "pergunta": "Pode uma sucção ser menor que o recalque?", "resposta": "Não; seu DN não deve ser inferior ao da tubulação de recalque."}, {"id": "5.1.6.6", "tit": "Nível do recalque", "pag": 20, "nivel": 3, "resumo": "Exige atingir nível superior ao logradouro e impedir refluxo com dispositivos adequados.", "quadro": null, "pergunta": "Basta conectar o recalque em qualquer cota baixa?", "resposta": "Não; é preciso a condição de elevação e a impossibilidade de refluxo."}, {"id": "5.1.6.7", "tit": "Volume útil da caixa", "pag": 20, "nivel": 3, "resumo": "Permite calcular o volume entre os níveis operacionais pela vazão da bomba e pelo intervalo de partidas.", "quadro": null, "pergunta": "Qual Vu para Q = 0,3 m³/min e t = 10 min?", "resposta": "Vu = Q·t/4 = 0,75 m³."}, {"id": "5.1.6.8", "tit": "Intervalo entre partidas", "pag": 20, "nivel": 3, "resumo": "Recomenda intervalo de pelo menos dez minutos para preservar os equipamentos.", "quadro": null, "pergunta": "Dez minutos é recomendação ou proibição absoluta neste item?", "resposta": "É intervalo mínimo recomendado; preservar a força do verbo do texto."}, {"id": "5.1.6.9", "tit": "Capacidade recomendada da bomba", "pag": 20, "nivel": 3, "resumo": "Recomenda capacidade da bomba de pelo menos duas vezes a vazão afluente.", "quadro": null, "pergunta": "Qual relação de vazões a norma recomenda?", "resposta": "Capacidade da bomba no mínimo igual a duas vezes a vazão afluente de esgoto."}, {"id": "5.1.6.10", "tit": "Volume total da caixa", "pag": 20, "nivel": 3, "resumo": "Acrescenta ao volume útil o espaço ocupado por componentes internos.", "quadro": null, "pergunta": "Vu e Vt são necessariamente iguais?", "resposta": "Não; Vt inclui os volumes ocupados por bombas submersíveis, tubulações e acessórios internos."}, {"id": "5.1.6.11", "tit": "Tempo de detenção", "pag": 20, "nivel": 3, "resumo": "Calcula a permanência do esgoto com o volume total e a vazão média afluente.", "quadro": null, "pergunta": "Qual detenção para Vt = 1 m³ e q = 0,1 m³/min?", "resposta": "d = Vt/q = 10 min; a vazão é a média afluente, não a capacidade da bomba."}, {"id": "5.1.6.12", "tit": "Detenção máxima", "pag": 20, "nivel": 3, "resumo": "Limita o tempo de detenção para preservar as condições de aerobiose.", "quadro": null, "pergunta": "Qual é o limite e sua força normativa?", "resposta": "A detenção não deve ultrapassar 30 min."}, {"id": "5.2", "tit": "Dimensionar a ventilação", "pag": 20, "nivel": 2, "resumo": "Relaciona o método da coleta aos critérios de dimensionamento da ventilação.", "quadro": "terminal", "pergunta": "Qual escolha anterior interfere no método de ventilação?", "resposta": "Ter dimensionado a coleta por método hidráulico ou pelo método UHC."}, {"id": "5.2.1", "tit": "Escolher o método de ventilação", "pag": 20, "nivel": 3, "resumo": "Exige Anexo D quando a coleta foi dimensionada pelo método hidráulico do Anexo B.", "quadro": "terminal", "pergunta": "Se usei o Anexo B, posso misturar livremente a ventilação da Tabela 8?", "resposta": "O item encaminha a ventilação ao Anexo D; no outro caso, usar os critérios de 5.2.2."}, {"id": "5.2.2", "tit": "Critérios da ventilação secundária", "pag": 20, "nivel": 3, "resumo": "Distingue ramal, circuito, complementar, coluna, barrilete e alívio nas tabelas e proporções aplicáveis.", "quadro": "terminal", "pergunta": "Qual tabela uso para a coluna de ventilação?", "resposta": "Tabela 2; considerar no comprimento o trecho primário entre a ligação da coluna e a extremidade aberta."}, {"id": "Tabela 8", "tit": "Ramais de ventilação", "pag": 21, "nivel": 3, "resumo": "Separa grupos com e sem bacia para definir o mínimo do ramal ventilador.", "quadro": "banheiro", "pergunta": "Com bacia, 18 UHC exigem qual mínimo?", "resposta": "DN 75; DN 50 atende somente até 17 UHC nessa categoria."}, {"id": "6", "tit": "Execução", "pag": 21, "nivel": 1, "resumo": "Vincula a obra ao projeto e indica procedimentos de execução, ensaios e identificação das tubulações.", "quadro": "ensaio", "pergunta": "Qual anexo trata dos ensaios de recebimento?", "resposta": "Anexo G; os cuidados de execução estão no Anexo E e a pintura remete à NBR 6493 citada."}, {"id": "7", "tit": "Manutenção", "pag": 21, "nivel": 1, "resumo": "Exige preservar estanqueidade e desobstrução e recomenda verificação periódica.", "quadro": "inspecao", "pergunta": "A vedação precisa ser só contra água?", "resposta": "Não; manter estanqueidade à água e ao ar, com a exceção das aberturas de ventilação indicadas."}, {"id": "8", "tit": "Qualidade", "pag": 21, "nivel": 1, "resumo": "Distribui responsabilidades e controles em projeto, material, execução, uso e manutenção.", "quadro": null, "pergunta": "Qualidade é verificada apenas no fim da obra?", "resposta": "Não; envolve todas as fases do sistema."}, {"id": "8.1", "tit": "Considerações sobre qualidade", "pag": 21, "nivel": 2, "resumo": "Prevê responsabilidades, procedimentos e garantia ao longo das fases do empreendimento.", "quadro": null, "pergunta": "Quem deve definir responsabilidades e procedimentos?", "resposta": "Os intervenientes do processo, nas condições previstas para a garantia da qualidade."}, {"id": "8.1.1", "tit": "Responsabilidades definidas", "pag": 21, "nivel": 3, "resumo": "Exige identificar os participantes e estabelecer procedimentos básicos de garantia.", "quadro": null, "pergunta": "Pode deixar a atribuição de responsabilidades para depois de um defeito?", "resposta": "Não; elas devem ser definidas no processo."}, {"id": "8.1.2", "tit": "Qualidade em todas as fases", "pag": 21, "nivel": 3, "resumo": "Exige garantia desde o projeto até a manutenção em uso.", "quadro": null, "pergunta": "A escolha correta do material sozinha garante a qualidade?", "resposta": "Não; projeto, execução, uso, operação e manutenção também participam."}, {"id": "8.2", "tit": "Responsabilidades dos intervenientes", "pag": 21, "nivel": 2, "resumo": "Organiza deveres de empreendedor, contratante, projetista, executor, fornecedor, órgãos, usuário e gestor.", "quadro": null, "pergunta": "Como achar quem responde por cada atividade?", "resposta": "Consultar os subitens de 8.2, não atribuir tudo ao instalador."}, {"id": "8.2.1", "tit": "Empreendedor", "pag": 21, "nivel": 3, "resumo": "Atribui ao empreendedor diretrizes básicas e orçamentárias do empreendimento.", "quadro": null, "pergunta": "Quem fornece as diretrizes orçamentárias?", "resposta": "O empreendedor, segundo este subitem."}, {"id": "8.2.2", "tit": "Contratante", "pag": 21, "nivel": 3, "resumo": "Atribui ao contratante requisitos, aceitação, gerenciamento e orientação para o uso.", "quadro": null, "pergunta": "Quem define os critérios de aceitação do projeto?", "resposta": "O contratante, entre as atribuições indicadas."}, {"id": "8.2.3", "tit": "Projetista", "pag": 21, "nivel": 3, "resumo": "Relaciona projeto, assistência e documentação final e de manutenção.", "quadro": null, "pergunta": "O projetista participa do como construído?", "resposta": "Sim; o item inclui elaborar esse projeto e assessorar na documentação de uso e manutenção."}, {"id": "8.2.4", "tit": "Executor", "pag": 21, "nivel": 3, "resumo": "Atribui ao executor execução conforme projeto, ensaios e registro das alterações.", "quadro": "ensaio", "pergunta": "Pode mudar o projeto na obra sem consultar o projetista?", "resposta": "As alterações por construtibilidade exigem aprovação prévia do projetista."}, {"id": "8.2.5", "tit": "Fornecedor de componentes", "pag": 22, "nivel": 3, "resumo": "Exige fornecimento de especificações e de produtos que atendam às normas.", "quadro": null, "pergunta": "O fornecedor só entrega a peça, sem informação técnica?", "resposta": "Não; deve fornecer suas especificações e produto conforme a normalização."}, {"id": "8.2.6", "tit": "Órgãos públicos", "pag": 22, "nivel": 3, "resumo": "Atribui aos órgãos os critérios e as diretrizes para ligação à rede pública.", "quadro": null, "pergunta": "Quem define as diretrizes construtivas da ligação pública?", "resposta": "Os órgãos públicos competentes, conforme o item."}, {"id": "8.2.7", "tit": "Usuário", "pag": 22, "nivel": 3, "resumo": "Vincula o uso às recomendações do manual.", "quadro": null, "pergunta": "Como o usuário participa da preservação do sistema?", "resposta": "Seguindo as recomendações de uso, operação e manutenção."}, {"id": "8.2.8", "tit": "Gestor do sistema", "pag": 22, "nivel": 3, "resumo": "Relaciona intervenções necessárias e atendimento ao manual.", "quadro": null, "pergunta": "O gestor pode ignorar o manual depois da entrega?", "resposta": "Não; deve seguir suas recomendações e realizar as intervenções necessárias."}, {"id": "8.3", "tit": "Procedimentos de qualidade", "pag": 22, "nivel": 2, "resumo": "Exige relacionar as fases abrangidas nos contratos de garantia da qualidade.", "quadro": null, "pergunta": "Quais fases aparecem nos procedimentos de 8.3?", "resposta": "Projeto, execução e uso, operação e manutenção."}, {"id": "8.3.1", "tit": "Qualidade no projeto", "pag": 22, "nivel": 3, "resumo": "Distingue o controle do processo de projetar e o controle do produto entregue.", "quadro": "predio", "pergunta": "Conferir somente o DN cobre todo o controle do projeto?", "resposta": "Não; também entram traçado, compatibilização, execução, manutenção e documentação."}, {"id": "8.3.1.1", "tit": "Controle do processo de projeto", "pag": 22, "nivel": 3, "resumo": "Prevê verificar alternativas, requisitos, normas, compatibilização e dimensionamento e registrar não conformidades.", "quadro": "predio", "pergunta": "O que fazer com uma incompatibilidade encontrada?", "resposta": "Registrar a não conformidade e a solução, realimentando as diretrizes do projeto."}, {"id": "8.3.1.2", "tit": "Controle do produto de projeto", "pag": 22, "nivel": 3, "resumo": "Confere compatibilização e detalhamento da documentação para construir e manter o sistema.", "quadro": "predio", "pergunta": "O desenho final precisa permitir manutenção?", "resposta": "Sim; a facilidade de construção e de manutenção integra o controle do produto."}, {"id": "8.3.2", "tit": "Qualidade na execução", "pag": 22, "nivel": 3, "resumo": "Separa acompanhamento do processo de obra e verificação do produto executado.", "quadro": "ensaio", "pergunta": "Qual controle não pode faltar no produto final?", "resposta": "Os ensaios de recebimento, além das verificações e dos registros indicados."}, {"id": "8.3.2.1", "tit": "Controle do processo de execução", "pag": 22, "nivel": 3, "resumo": "Acompanha projeto e normas e registra alterações e não conformidades durante a obra.", "quadro": "ensaio", "pergunta": "Para que registrar as alterações de execução?", "resposta": "Para permitir o como construído e incorporar as soluções ao histórico do projeto."}, {"id": "8.3.2.2", "tit": "Controle do produto executado", "pag": 22, "nivel": 3, "resumo": "Exige documentação adequada à manutenção, ensaios e registros de não conformidades.", "quadro": "ensaio", "pergunta": "Um teste informal substitui o recebimento indicado?", "resposta": "Não; realizar os ensaios de recebimento e os registros previstos."}, {"id": "8.3.3", "tit": "Qualidade no uso e na manutenção", "pag": 22, "nivel": 3, "resumo": "Vincula a operação aos manuais e ao retorno das ocorrências para o projeto.", "quadro": "inspecao", "pergunta": "Por que registrar defeitos encontrados no uso?", "resposta": "Para corrigir o sistema e realimentar as diretrizes de projeto e execução."}, {"id": "Anexo A", "tit": "Simbologia — informativo", "pag": 23, "nivel": 1, "resumo": "Reúne símbolos para reconhecer aparelhos, caixas e dispositivos nos desenhos do sistema.", "quadro": "predio", "pergunta": "Onde encontrar o símbolo de uma caixa de inspeção?", "resposta": "No Anexo A, página 23; CI identifica caixa de inspeção."}, {"id": "Anexo B", "tit": "Método hidráulico de dimensionamento — normativo", "pag": 24, "nivel": 1, "resumo": "Apresenta o método hidráulico alternativo às UHC para dimensionar a coleta e o transporte de esgoto.", "quadro": "predio", "pergunta": "Usar o método hidráulico dispensa os diâmetros mínimos dos aparelhos?", "resposta": "Não; os mínimos da Tabela 3 continuam exigidos por 5.1."}, {"id": "B.1", "tit": "Condições gerais do método hidráulico", "pag": 24, "nivel": 2, "resumo": "Define que o roteiro hidráulico abrange ramais, tubos de queda, subcoletores e coletor em regime permanente.", "quadro": null, "pergunta": "Quais trechos podem ser calculados por esse roteiro?", "resposta": "Ramais de descarga e esgoto, TQs, subcoletores e coletor predial."}, {"id": "B.2", "tit": "Roteiro de cálculo hidráulico", "pag": 24, "nivel": 2, "resumo": "Organiza o cálculo das vazões e dos diâmetros dos trechos verticais e horizontais.", "quadro": null, "pergunta": "Qual a diferença básica entre os dois grupos do roteiro?", "resposta": "B.2.1 trata do tubo de queda; B.2.2, dos ramais e coletores."}, {"id": "B.2.1", "tit": "Dimensionamento hidráulico do tubo de queda", "pag": 24, "nivel": 3, "resumo": "Relaciona diâmetro, vazão simultânea, rugosidade e ocupação da seção do tubo de queda.", "quadro": "predio", "pergunta": "Pode-se somar todas as vazões como se todos os aparelhos funcionassem juntos?", "resposta": "O método estima simultaneidade por tipo de aparelho e fator de falha, antes de calcular a vazão de projeto."}, {"id": "Tabela B.1", "tit": "Aparelhos simultâneos para fator de falha de 1,0%", "pag": 25, "nivel": 3, "resumo": "Fornece a simultaneidade estimada para o fator de falha de 1,0%, conforme quantidade e duração das descargas.", "quadro": null, "pergunta": "Basta conhecer o número total de aparelhos para usar a tabela?", "resposta": "Não; também são necessários o intervalo entre descargas e a duração média, além do fator de falha escolhido."}, {"id": "Tabela B.2", "tit": "Aparelhos simultâneos para fator de falha de 2,5%", "pag": 34, "nivel": 3, "resumo": "Apresenta a simultaneidade calculada para fator de falha de 2,5%.", "quadro": null, "pergunta": "Qual parâmetro distingue esta tabela da B.1?", "resposta": "O fator de falha: 2,5% na B.2 e 1,0% na B.1."}, {"id": "Tabela B.3", "tit": "Aparelhos simultâneos para fator de falha de 5,0%", "pag": 43, "nivel": 3, "resumo": "Apresenta a simultaneidade para fator de falha de 5,0%, com subdivisões pelos intervalos de utilização.", "quadro": null, "pergunta": "Qual tabela serve ao exemplo de 35 aparelhos, intervalo de 15 min, duração de 10 s e falha de 5%?", "resposta": "Tabela B.3 c); o exemplo de B.2.1.3 obtém dois aparelhos simultâneos."}, {"id": "Tabela B.4", "tit": "Vazões unitárias dos aparelhos sanitários", "pag": 52, "nivel": 3, "resumo": "Lista vazões médias por aparelho para compor a vazão hidráulica de projeto.", "quadro": "banheiro", "pergunta": "A vazão de bacia com caixa é a mesma da bacia com válvula?", "resposta": "Não: a tabela indica 0,96 L/s para caixa e 1,70 L/s para válvula; considerar prioritariamente o fabricante quando aplicável."}, {"id": "Tabela B.5", "tit": "Capacidades hidráulicas dos tubos de queda plásticos", "pag": 52, "nivel": 3, "resumo": "Relaciona vazão, ocupação da seção e DN do TQ para coeficiente de Manning de 0,010.", "quadro": "predio", "pergunta": "O que precisa ser escolhido além da vazão para consultar esta tabela?", "resposta": "A taxa de ocupação; conferir o critério de escoamento anular de B.2.1.4 e o material do tubo."}, {"id": "B.2.2", "tit": "Dimensionamento hidráulico dos ramais e coletores", "pag": 52, "nivel": 3, "resumo": "Calcula trechos horizontais com vazão, rugosidade e declividade, distinguindo as condições de enchimento.", "quadro": "decl", "pergunta": "No ramal de descarga, de onde vem a vazão usada no cálculo?", "resposta": "Do aparelho conectado: Qe = qi, mantendo os critérios de declividade e os mínimos pertinentes."}, {"id": "Tabela B.6", "tit": "Capacidades de ramais à meia seção para tubulação plástica", "pag": 53, "nivel": 3, "resumo": "Fornece vazões máximas para diferentes DN e declividades com Manning de 0,010 e escoamento à meia seção.", "quadro": "decl", "pergunta": "Qual é a vazão tabelada para DN 100 a 2%?", "resposta": "4,758 L/s, nas condições de material e enchimento da tabela."}, {"id": "Anexo C", "tit": "Suficiência da ventilação primária — normativo", "pag": 54, "nivel": 1, "resumo": "Verifica se a ventilação primária protege os fechos hídricos contra os efeitos calculados no sistema.", "quadro": "fecho", "pergunta": "É correto dispensar ventilação secundária só porque o prédio parece pequeno?", "resposta": "Não; a suficiência da primária deve ser verificada pelo modelo do Anexo C quando se adota apenas essa forma de ventilação."}, {"id": "C.1", "tit": "Condições gerais da verificação de ventilação", "pag": 54, "nivel": 2, "resumo": "Estabelece comparações entre efeitos admissíveis e resultantes de perdas de fecho e pressões.", "quadro": "fecho", "pergunta": "Quais verificações precisam ser atendidas em conjunto?", "resposta": "Ha,i ≥ Hr,i, Da,s ≥ Dr e Sa,s ≥ Sr."}, {"id": "C.2", "tit": "Variáveis admissíveis e resultantes", "pag": 54, "nivel": 2, "resumo": "Separa os limites de resistência dos desconectores dos efeitos produzidos pelo funcionamento e pelo ambiente.", "quadro": "fecho", "pergunta": "Qual a diferença entre uma variável admissível e uma resultante?", "resposta": "A admissível é o limite suportado; a resultante é a solicitação calculada para comparar com esse limite."}, {"id": "C.2.1", "tit": "Variáveis admissíveis", "pag": 54, "nivel": 3, "resumo": "Calcula os limites de perda de altura e de pressão que os desconectores do sistema podem suportar.", "quadro": "fecho", "pergunta": "A análise pode considerar só um sifão escolhido por conveniência?", "resposta": "Não; é preciso considerar os tipos de desconectores do sistema e os limites que governam a verificação."}, {"id": "C.2.1.1", "tit": "Perda admissível de altura do fecho hídrico", "pag": 54, "nivel": 3, "resumo": "Desconta a evaporação da altura inicial do fecho para obter a perda admissível disponível.", "quadro": "fecho", "pergunta": "Como entram a evaporação e o tempo sem uso na conta?", "resposta": "Ha = Ho − he, com he = Ce·π·(1−y)·Δt; 4,5 semanas é o período usual adotado no exemplo, não uma duração universal obrigatória."}, {"id": "C.2.1.2", "tit": "Depressão admissível no sistema", "pag": 55, "nivel": 3, "resumo": "Determina a resistência de cada tipo de desconector à depressão e toma o menor limite para o sistema.", "quadro": "fecho", "pergunta": "Qual desconector governa a depressão admissível do sistema?", "resposta": "Aquele que resultar no menor Da,i, após considerar sua geometria e a altura admissível disponível."}, {"id": "C.2.1.3", "tit": "Sobrepressão admissível no sistema", "pag": 55, "nivel": 3, "resumo": "Calcula os limites de sobrepressão dos desconectores conforme a relação entre suas câmaras.", "quadro": "fecho", "pergunta": "Como obter a sobrepressão admissível do conjunto?", "resposta": "Calcular Sa,i para cada tipo e adotar o menor valor, usando a expressão pertinente a Rv menor ou maior/igual a 1."}, {"id": "Tabela C.1", "tit": "Altura inicial e coeficiente de evaporação de desconectores", "pag": 56, "nivel": 3, "resumo": "Fornece parâmetros de desconectores para calcular a perda de fecho por evaporação.", "quadro": "fecho", "pergunta": "Quais dados desta tabela entram em Ha = Ho − he?", "resposta": "A altura inicial Ho e o coeficiente Ce; o cabeçalho expressa Ce em múltiplos de 10⁻³."}, {"id": "Tabela C.2", "tit": "Pressão de vapor em função da temperatura ambiente", "pag": 56, "nivel": 3, "resumo": "Relaciona temperatura e pressão de vapor saturado usada na estimativa de evaporação.", "quadro": "fecho", "pergunta": "Qual pressão de vapor a tabela indica para 30 °C?", "resposta": "4.240,3 Pa; a temperatura altera π na expressão de evaporação."}, {"id": "Tabela C.3", "tit": "Relação de volumes das câmaras dos desconectores", "pag": 57, "nivel": 3, "resumo": "Apresenta Rv para diferentes configurações de desconector, parâmetro dos limites de pressão.", "quadro": "fecho", "pergunta": "Qual Rv é apresentado para o sifão incorporado à bacia?", "resposta": "0,85; usar os dados correspondentes ao desconector efetivamente considerado."}, {"id": "C.2.2", "tit": "Variáveis resultantes", "pag": 57, "nivel": 3, "resumo": "Reúne as solicitações calculadas de auto-sifonagem, depressão e sobrepressão.", "quadro": "fecho", "pergunta": "Com quais limites devem ser comparadas essas solicitações?", "resposta": "Com Ha,i, Da,s e Sa,s, respectivamente, conforme C.3."}, {"id": "C.2.2.1", "tit": "Perda de fecho por auto-sifonagem", "pag": 57, "nivel": 3, "resumo": "Avalia a perda por auto-sifonagem e explicita a hipótese de desconsiderá-la quando os ramais têm escoamento livre.", "quadro": "fecho", "pergunta": "Por que o roteiro considera Hr,i = 0 nessa hipótese?", "resposta": "Porque assume escoamento livre nos ramais, conforme a premissa do dimensionamento; não é uma dispensa independente dessa condição."}, {"id": "C.2.2.2", "tit": "Depressão máxima resultante", "pag": 57, "nivel": 3, "resumo": "Combina os efeitos de sifonagem induzida, tiragem térmica, vento e pressão ambiental.", "quadro": "fecho", "pergunta": "Somam-se diretamente todas as depressões máximas?", "resposta": "O roteiro toma o maior módulo entre os efeitos de sifonagem e de tiragem/vento e acrescenta a parcela ambiental pertinente."}, {"id": "C.2.2.2.1", "tit": "Depressão por sifonagem induzida", "pag": 57, "nivel": 3, "resumo": "Relaciona a depressão induzida à vazão de ar e às perdas no tubo de queda e nos ramais.", "quadro": "predio", "pergunta": "Qual expressão básica relaciona perda de pressão e vazão de ar?", "resposta": "Dr,si = kTq·Qar²; os coeficientes e a geometria devem ser determinados pelo roteiro, não escolhidos só pelo número de pavimentos."}, {"id": "Tabela C.4", "tit": "Coeficiente α para o tubo de queda", "pag": 58, "nivel": 3, "resumo": "Associa o diâmetro interno do TQ ao coeficiente usado para calcular a vazão de ar.", "quadro": "predio", "pergunta": "Qual α corresponde a TQ de 100 mm nesta tabela?", "resposta": "24,3; o parâmetro é usado na expressão de Qar do Anexo C."}, {"id": "Tabela C.5", "tit": "Coeficiente de perda de pressão do ramal", "pag": 58, "nivel": 3, "resumo": "Apresenta coeficientes de perda conforme as condições indicadas para o ramal e sua descarga.", "quadro": null, "pergunta": "Onde procurar o coeficiente k do ramal no cálculo das depressões?", "resposta": "Na Tabela C.5, conferindo a configuração e as condições de vazão da linha; o exemplo com entrada suave de bacia usa k = 9."}, {"id": "C.2.2.2.2", "tit": "Depressão por tiragem térmica e vento", "pag": 59, "nivel": 3, "resumo": "Considera altura, temperaturas, vento e terminal para avaliar o efeito de tiragem e vento.", "quadro": "terminal", "pergunta": "As temperaturas desta expressão são digitadas em graus Celsius?", "resposta": "Não; as temperaturas absolutas são usadas em kelvins, e a velocidade do vento em m/s."}, {"id": "C.2.2.2.3", "tit": "Depressão por variações da pressão ambiental", "pag": 60, "nivel": 3, "resumo": "Trata a parcela ambiental e a considera desprezível nas condições normais assumidas pelo roteiro.", "quadro": null, "pergunta": "Qual valor o exemplo admite para Dr,amb em condições normais?", "resposta": "Dr,amb = 0; não extrapolar essa hipótese sem verificar as condições do ambiente."}, {"id": "C.2.2.3", "tit": "Sobrepressão máxima resultante", "pag": 60, "nivel": 3, "resumo": "Combina os efeitos de sobrepressão e do ambiente, com hipóteses específicas sobre os pontos de ligação.", "quadro": "sobre", "pergunta": "Por que o exemplo pode chegar a Sr = 0?", "resposta": "Ele assume parcela ambiental nula e observância das soluções para evitar ligações nas zonas de sobrepressão; não é valor geral para qualquer traçado."}, {"id": "C.3", "tit": "Verificação final da suficiência da ventilação primária", "pag": 60, "nivel": 2, "resumo": "Conclui sobre a ventilação primária comparando todas as solicitações calculadas com seus limites.", "quadro": "fecho", "pergunta": "Basta passar na comparação de depressão para dispensar a secundária?", "resposta": "Não; todas as comparações de perda de fecho, depressão e sobrepressão precisam ser atendidas."}, {"id": "C.3.1", "tit": "Comparações dos efeitos com os limites admissíveis", "pag": 60, "nivel": 3, "resumo": "Estabelece as três desigualdades que demonstram suficiência da ventilação primária no modelo.", "quadro": "fecho", "pergunta": "Como expressar o critério de aprovação do modelo?", "resposta": "Ha,i ≥ Hr,i, Da,s ≥ Dr e Sa,s ≥ Sr, simultaneamente."}, {"id": "C.3.2", "tit": "Medidas quando a ventilação primária não é suficiente", "pag": 60, "nivel": 3, "resumo": "Permite revisar a geometria e os parâmetros do sistema ou prever ventilação secundária quando os limites são ultrapassados.", "quadro": "predio", "pergunta": "Qual é o próximo passo quando uma comparação falha?", "resposta": "Rever parâmetros como diâmetros e traçado e verificar novamente, ou prever ventilação secundária."}, {"id": "Figura C.1", "tit": "Esquema do TQ para o estudo das depressões", "pag": 61, "nivel": 3, "resumo": "Localiza a parte seca, curvas e trechos contribuintes usados no exemplo de cálculo das depressões.", "quadro": "predio", "pergunta": "Como a figura ajuda a definir o comprimento da parte seca?", "resposta": "Ela identifica ls e os trechos/ramais do exemplo; não fornece um comprimento universal para todos os prédios."}, {"id": "Anexo D", "tit": "Dimensionamento hidráulico da ventilação secundária — normativo", "pag": 62, "nivel": 1, "resumo": "Apresenta o roteiro de ramais e colunas de ventilação secundária pelo método hidráulico.", "quadro": "predio", "pergunta": "Que anexo acompanha a ventilação quando a coleta foi dimensionada pelo método hidráulico?", "resposta": "O Anexo D, conforme a vinculação estabelecida em 5.2.1."}, {"id": "D.1", "tit": "Condições gerais da ventilação secundária hidráulica", "pag": 62, "nivel": 2, "resumo": "Delimita o roteiro aos ramais e às colunas de ventilação secundária.", "quadro": null, "pergunta": "Este roteiro dimensiona diretamente a rede de esgoto?", "resposta": "Não; ele trata da ventilação secundária, enquanto o Anexo B trata da coleta e do transporte."}, {"id": "D.2", "tit": "Roteiro de cálculo da ventilação secundária", "pag": 62, "nivel": 2, "resumo": "Divide o dimensionamento entre o ramal ligado ao esgoto e a coluna que transporta o ar.", "quadro": "predio", "pergunta": "Quais são as duas partes do roteiro?", "resposta": "D.2.1 para o ramal e D.2.2 para a coluna de ventilação."}, {"id": "D.2.1", "tit": "Ramal de ventilação secundária", "pag": 62, "nivel": 3, "resumo": "Permite obter o DN do ramal ventilador a partir do diâmetro do ramal de descarga ou de esgoto conectado.", "quadro": "banheiro", "pergunta": "Qual tabela é usada nesse método para o ramal ventilador?", "resposta": "Tabela D.1; não confundir com a Tabela 8 do método indicado em 5.2.2."}, {"id": "Tabela D.1", "tit": "Diâmetro do ramal de ventilação pelo método hidráulico", "pag": 62, "nivel": 3, "resumo": "Relaciona o DN do ramal de descarga ou esgoto ao DN de seu ramal ventilador.", "quadro": "banheiro", "pergunta": "Para ramal de esgoto DN 100, qual ventilação a tabela indica?", "resposta": "Ramal ventilador DN 50, no contexto do método do Anexo D."}, {"id": "D.2.2", "tit": "Coluna de ventilação secundária", "pag": 62, "nivel": 3, "resumo": "Dimensiona a coluna a partir da vazão de ar, do comprimento e das perdas admitidas.", "quadro": "predio", "pergunta": "O comprimento da coluna termina no ponto onde ela encontra o ventilador primário?", "resposta": "Não; deve incluir também o trecho primário até a extremidade aberta, quando pertinente, conforme 5.2.2 d)."}, {"id": "D.2.2.1", "tit": "Vazão de ar e cálculo iterativo da coluna", "pag": 62, "nivel": 3, "resumo": "Estima a vazão de ar da coluna como dois terços da vazão de ar do TQ e resolve o diâmetro por iteração.", "quadro": "predio", "pergunta": "Quais unidades entram na expressão com coeficiente 4,06?", "resposta": "Dcv e Lv em milímetros e Q'ar em L/min; o roteiro considera perda máxima de 25 mmca e adota DN comercial imediatamente superior ao calculado."}, {"id": "Tabela D.2", "tit": "Coeficiente de perda distribuída da coluna de ventilação", "pag": 62, "nivel": 3, "resumo": "Fornece o coeficiente f usado na iteração entre diâmetro e perda de carga da coluna.", "quadro": null, "pergunta": "Qual f é indicado para DN 75?", "resposta": "0,037; a escolha precisa ser compatível com o diâmetro resultante da iteração."}, {"id": "Anexo E", "tit": "Cuidados de execução — informativo", "pag": 63, "nivel": 1, "resumo": "Organiza cuidados de manuseio, juntas, assentamento, fixação e proteção durante a obra.", "quadro": null, "pergunta": "Esse anexo é classificado como normativo ou informativo?", "resposta": "Informativo; consulte também os requisitos de execução da seção 6 e as normas dos componentes."}, {"id": "E.1", "tit": "Manuseio de materiais", "pag": 63, "nivel": 2, "resumo": "Orienta transporte e armazenamento conforme as normas de materiais e as instruções do fabricante.", "quadro": null, "pergunta": "O que consultar quando não houver norma específica de manuseio?", "resposta": "As instruções do fabricante, sem desconsiderar as demais normas aplicáveis."}, {"id": "E.2", "tit": "Juntas", "pag": 63, "nivel": 2, "resumo": "Trata da estanqueidade, acomodação dos movimentos e preservação da seção de passagem nas juntas.", "quadro": null, "pergunta": "É aceitável fazer uma bolsa aquecendo e alargando o tubo?", "resposta": "O texto veda juntas que deformem fisicamente o tubo, citando expressamente esse procedimento."}, {"id": "E.3", "tit": "Assentamento em valas", "pag": 63, "nivel": 2, "resumo": "Descreve preparo do fundo, espaço de montagem e reaterro que suportem e protejam as tubulações.", "quadro": "decl", "pergunta": "Pode-se apoiar o tubo sobre pedras pontiagudas no fundo da vala?", "resposta": "Não; o preparo descrito remove materiais perfurantes e cria suporte firme, com material adequado ao redor do tubo."}, {"id": "E.4", "tit": "Proteção e fixação", "pag": 63, "nivel": 2, "resumo": "Relaciona suportes, movimentações térmicas e proteção à manutenção da integridade e da declividade.", "quadro": "decl", "pergunta": "A que situação se refere a folga de 30 mm?", "resposta": "Ao acesso ao redor de componentes aparentes que necessitam proteção contra corrosão atmosférica, para aplicar revestimento; não é folga universal de qualquer tubo."}, {"id": "E.5", "tit": "Proteção durante a obra", "pag": 63, "nivel": 2, "resumo": "Indica proteção das aberturas e das tubulações contra resíduos, esforços e deslocamentos durante a execução.", "quadro": null, "pergunta": "Por que tampar as aberturas durante a obra?", "resposta": "Para impedir entrada de materiais estranhos; as proteções devem permanecer durante toda a execução."}, {"id": "Anexo F", "tit": "Cuidados de manutenção — informativo", "pag": 64, "nivel": 1, "resumo": "Reúne métodos de desobstrução, precauções de segurança e organização da manutenção.", "quadro": "inspecao", "pergunta": "O anexo autoriza usar qualquer método de desentupimento em qualquer material?", "resposta": "Não; compatibilidade com o material, resistência da instalação e capacitação do operador precisam ser consideradas."}, {"id": "F.1", "tit": "Cuidados mínimos na manutenção", "pag": 64, "nivel": 2, "resumo": "Orienta avaliar vedações, materiais e riscos antes de métodos químicos, pressurizados ou mecanizados.", "quadro": "inspecao", "pergunta": "Por que identificar o material antes de aplicar produto químico?", "resposta": "Para evitar que o produto danifique a tubulação; métodos mecanizados também exigem operador treinado e ferramenta compatível."}, {"id": "F.2", "tit": "Métodos usuais de desentupimento", "pag": 64, "nivel": 2, "resumo": "Apresenta alternativas mecânicas, pneumáticas e químicas conforme o tipo de obstrução e acesso.", "quadro": "inspecao", "pergunta": "Escolhe-se o método apenas pelo diâmetro do tubo?", "resposta": "Não; também importam material, natureza da obstrução, acesso e resistência a esforços e pressão."}, {"id": "F.2.1", "tit": "Remoção com vara ou arame", "pag": 64, "nivel": 3, "resumo": "Descreve a remoção de materiais lançados indevidamente pelo acesso a montante mais próximo.", "quadro": "inspecao", "pergunta": "Por onde introduzir a vara para alcançar a obstrução?", "resposta": "Pelo ponto de acesso a montante mais próximo do local obstruído, usando elemento flexível que não danifique a instalação."}, {"id": "F.2.2", "tit": "Bombeamento com bomba de borracha", "pag": 64, "nivel": 3, "resumo": "Explica o desentupimento simples de pias e bacias por impulsos de pressão com desentupidor adequado.", "quadro": "banheiro", "pergunta": "Bombeamento aqui significa instalar uma estação de recalque?", "resposta": "Não; é a ação de uma bomba de borracha usada para desobstruir pequenos entupimentos."}, {"id": "F.2.3", "tit": "Desbloqueamento com haste flexível", "pag": 64, "nivel": 3, "resumo": "Apresenta hastes e pontas de desobstrução manuais ou mecanizadas compatíveis com os tubos.", "quadro": "inspecao", "pergunta": "A partir de qual DN o texto indica a haste flexível como adequada?", "resposta": "A partir de DN 75, observando a flexibilidade necessária para introdução e as características do serviço."}, {"id": "F.2.4", "tit": "Martelo pneumático", "pag": 64, "nivel": 3, "resumo": "Descreve a remoção por golpe de pressão e ressalta a resistência da instalação aos impactos.", "quadro": null, "pergunta": "É seguro aumentar a pressão sem avaliar a instalação?", "resposta": "Não; o método pede uso criterioso e consideração dos golpes de pressão e dos contragolpes."}, {"id": "F.2.5", "tit": "Raspagem", "pag": 64, "nivel": 3, "resumo": "Trata da retirada de incrustações por ferramentas compatíveis com o material da tubulação.", "quadro": "inspecao", "pergunta": "Qual é o DN de referência mínimo citado para raspagem?", "resposta": "DN 100; ainda é necessário avaliar o material para não danificar o tubo."}, {"id": "F.2.6", "tit": "Limpeza química", "pag": 64, "nivel": 3, "resumo": "Aborda produtos que reagem com a obstrução e os riscos de lesão e dano ao sistema.", "quadro": null, "pergunta": "O fato de um produto desobstruir permite usá-lo sem verificar o material?", "resposta": "Não; a compatibilidade, os riscos térmicos e a proteção do operador continuam essenciais."}, {"id": "F.2.7", "tit": "Limpeza de sifões e de seus ramais", "pag": 64, "nivel": 3, "resumo": "Indica desentupimento por bombeamento e acesso às partes removíveis dos sifões.", "quadro": "fecho", "pergunta": "Por que sifões com corpo removível facilitam a manutenção?", "resposta": "Eles oferecem acesso ao interior para limpeza; seus ramais também podem receber haste compatível."}, {"id": "F.2.8", "tit": "Localização de obstruções em coletores e TQs", "pag": 65, "nivel": 3, "resumo": "Usa os dispositivos de inspeção para localizar a obstrução e escolher o acesso de desentupimento.", "quadro": "inspecao", "pergunta": "Que ponto de inspeção o texto indica para introduzir a haste no coletor?", "resposta": "O acesso seco ou parcialmente seco mais próximo da obstrução, após localizar o trecho comprometido."}, {"id": "F.2.9", "tit": "Desentupimento de bacias sanitárias", "pag": 65, "nivel": 3, "resumo": "Apresenta o desentupidor de borracha e outras alternativas compatíveis com a bacia e o tipo de depósito.", "quadro": "banheiro", "pergunta": "Qual método simples o texto destaca para a bacia?", "resposta": "A bomba de borracha que pressuriza o sifão; a escolha de outros métodos depende da obstrução."}, {"id": "F.3", "tit": "Segurança na manutenção", "pag": 65, "nivel": 2, "resumo": "Trata da capacitação, proteção pessoal e proteção do ambiente nos serviços de desobstrução.", "quadro": null, "pergunta": "Desentupir exige somente força e uma ferramenta?", "resposta": "Não; exige compreender o problema, saber usar equipamentos e produtos e proteger pessoas e instalação."}, {"id": "F.3.1", "tit": "Compreensão do problema e habilidade técnica", "pag": 65, "nivel": 3, "resumo": "Associa a manutenção à identificação da causa e à habilidade para operar seus meios de limpeza.", "quadro": null, "pergunta": "Por que identificar a causa antes de escolher o equipamento?", "resposta": "Porque a obstrução e a instalação determinam o método e a ferramenta adequados."}, {"id": "F.3.2", "tit": "Prevenção de acidentes e danos", "pag": 65, "nivel": 3, "resumo": "Reforça os cuidados para evitar ferimentos ao operador e danos a aparelhos e tubulações.", "quadro": null, "pergunta": "A proteção deve se limitar ao operador?", "resposta": "Não; também devem ser protegidos os aparelhos sanitários e o sistema de esgoto."}, {"id": "F.3.3", "tit": "Equipamentos de proteção individual", "pag": 65, "nivel": 3, "resumo": "Indica proteção individual nos trabalhos de manutenção, especialmente ao usar produtos químicos.", "quadro": null, "pergunta": "Quais proteções o texto cita expressamente?", "resposta": "Luvas e óculos protetores, entre os EPI adequados ao serviço."}, {"id": "F.3.4", "tit": "Limpeza após uso de produtos químicos", "pag": 65, "nivel": 3, "resumo": "Orienta remover resíduos químicos das superfícies expostas dos aparelhos ao terminar a intervenção.", "quadro": "banheiro", "pergunta": "Basta desobstruir e deixar o produto na superfície?", "resposta": "Não; as superfícies expostas devem ser lavadas com detergentes para retirar substâncias capazes de lesar o usuário."}, {"id": "F.3.5", "tit": "Proteção dos acabamentos", "pag": 65, "nivel": 3, "resumo": "Lembra a proteção dos acabamentos decorativos durante os serviços de manutenção.", "quadro": null, "pergunta": "O que além das tubulações pode ser afetado pela manutenção?", "resposta": "Os acabamentos do ambiente, que precisam ser protegidos durante o serviço."}, {"id": "F.3.6", "tit": "Contragolpes e expulsão de esgoto", "pag": 65, "nivel": 3, "resumo": "Explica os riscos de reação ao golpe de pressão e de saída de esgoto por inspeções abertas.", "quadro": "inspecao", "pergunta": "Por que proteger uma inspeção aberta ao usar martelo pneumático?", "resposta": "O golpe pode expulsar esgoto pelo acesso e provocar ferimentos, sujeira e danos; contragolpes também ameaçam o operador."}, {"id": "F.4", "tit": "Inspeção periódica", "pag": 65, "nivel": 2, "resumo": "Recomenda organizar inspeções e registros para reconhecer falhas e planejar futuras manutenções.", "quadro": "inspecao", "pergunta": "A manutenção só deve começar quando houver entupimento?", "resposta": "O anexo recomenda inspeções periódicas para detectar problemas ao longo do uso."}, {"id": "F.4.1", "tit": "Planejamento das inspeções", "pag": 65, "nivel": 3, "resumo": "Recomenda planejar inspeções periódicas para detectar defeitos associados ao uso e ao tempo.", "quadro": "inspecao", "pergunta": "O texto fixa um intervalo único de inspeção para todo prédio?", "resposta": "Não fixa nesse item um período universal; recomenda planejar a verificação periódica do sistema."}, {"id": "F.4.2", "tit": "Roteiros dos pontos críticos", "pag": 65, "nivel": 3, "resumo": "Recomenda roteiros de inspeção ajustados progressivamente ao funcionamento real da instalação.", "quadro": "inspecao", "pergunta": "O roteiro elaborado pelo projeto nunca pode ser revisto?", "resposta": "Pode e deve ser ajustado à experiência de funcionamento, conforme a recomendação do anexo."}, {"id": "F.4.3", "tit": "Fichas de manutenção", "pag": 65, "nivel": 3, "resumo": "Recomenda registrar e arquivar os serviços para apoiar o planejamento e informar os responsáveis.", "quadro": "inspecao", "pergunta": "Para que serve a ficha de cada manutenção?", "resposta": "Para documentar o serviço e subsidiar intervenções futuras, mantendo o histórico acessível aos responsáveis."}, {"id": "Anexo G", "tit": "Ensaios de recebimento — normativo", "pag": 66, "nivel": 1, "resumo": "Define inspeções e ensaios de estanqueidade necessários ao recebimento do sistema.", "quadro": "ensaio", "pergunta": "Um sistema que sofreu ampliação pode entrar em uso sem ensaio?", "resposta": "O anexo exige inspeção e ensaio antes do funcionamento para sistemas novos e para os modificados ou ampliados."}, {"id": "G.1", "tit": "Condições exigíveis para recebimento", "pag": 66, "nivel": 2, "resumo": "Organiza as inspeções e a sequência dos ensaios antes e depois da colocação dos aparelhos.", "quadro": "ensaio", "pergunta": "Em que ordem entram os ensaios de água/ar e de fumaça?", "resposta": "Água ou ar antes dos aparelhos; fumaça depois da colocação dos aparelhos."}, {"id": "G.1.1", "tit": "Inspeção e ensaio antes do funcionamento", "pag": 66, "nivel": 3, "resumo": "Inclui o sistema de ventilação na verificação prévia do sistema novo ou alterado.", "quadro": "ensaio", "pergunta": "A ventilação fica fora da inspeção de recebimento?", "resposta": "Não; o sistema de esgoto a ensaiar inclui também o subsistema de ventilação."}, {"id": "G.1.2", "tit": "Conferência prévia de fixação e limpeza", "pag": 66, "nivel": 3, "resumo": "Determina verificar a fixação e a ausência de materiais estranhos antes dos ensaios.", "quadro": "ensaio", "pergunta": "Que inspeções antecedem o ensaio de estanqueidade?", "resposta": "Conferir fixação adequada e verificar se existe material estranho dentro do sistema."}, {"id": "G.1.3", "tit": "Ensaio antes da colocação dos aparelhos", "pag": 66, "nivel": 3, "resumo": "Exige testar a tubulação com água ou ar, sem vazamentos, antes da instalação dos aparelhos.", "quadro": "ensaio", "pergunta": "É obrigatório fazer os dois ensaios, água e ar, nessa etapa?", "resposta": "O texto estabelece água ou ar, conforme G.2.1 e G.2.2, sem apresentar vazamentos."}, {"id": "G.1.4", "tit": "Ensaio final após a colocação dos aparelhos", "pag": 66, "nivel": 3, "resumo": "Prevê o ensaio final de fumaça depois que os aparelhos estão instalados.", "quadro": "ensaio", "pergunta": "Água ou ar antes dos aparelhos dispensam a etapa final?", "resposta": "Não; depois da colocação dos aparelhos, o sistema deve passar pelo ensaio de fumaça."}, {"id": "G.2", "tit": "Procedimentos dos ensaios", "pag": 66, "nivel": 2, "resumo": "Detalha as condições de preparo, pressão e duração dos ensaios de água, ar e fumaça.", "quadro": "ensaio", "pergunta": "Qual duração aparece nos três procedimentos?", "resposta": "15 minutos, respeitando as pressões e o preparo específico de cada ensaio."}, {"id": "G.2.1", "tit": "Ensaio com água", "pag": 66, "nivel": 3, "resumo": "Usa água até o transbordamento da abertura mais alta, controlando a carga e o tempo de observação.", "quadro": "ensaio", "pergunta": "Quais são o tempo e a carga máxima do ensaio com água?", "resposta": "15 min e carga hidrostática não superior a 60 kPa, aproximadamente 6 mca."}, {"id": "G.2.2", "tit": "Ensaio com ar", "pag": 66, "nivel": 3, "resumo": "Mantém pressão uniforme de ar no sistema tamponado, sem reposição durante o período de ensaio.", "quadro": "ensaio", "pergunta": "Qual pressão deve permanecer sem adicionar mais ar?", "resposta": "35 kPa por 15 min."}, {"id": "G.2.3", "tit": "Ensaio final com fumaça", "pag": 66, "nivel": 3, "resumo": "Preenche os fechos e verifica a manutenção da pressão de fumaça depois de tamponar os ventiladores no momento indicado.", "quadro": "ensaio", "pergunta": "Quais pressão e tempo caracterizam o ensaio final?", "resposta": "0,25 kPa por 15 min, sem adicionar fumaça nesse período; antes, encher os fechos e tampar cada ventilador quando sair fumaça."}, {"id": "Anexo H", "tit": "Referências bibliográficas — informativo", "pag": 67, "nivel": 1, "resumo": "Identifica trabalhos técnicos e referências utilizados na elaboração dos modelos e procedimentos da edição de 1999.", "quadro": null, "pergunta": "A bibliografia substitui as prescrições e tabelas da norma?", "resposta": "Não; serve para localizar fontes e aprofundar os fundamentos, respeitando a edição e o alcance de cada referência."}, {"id": "Indice alfabetico", "tit": "Índice alfabético", "pag": 68, "nivel": 1, "resumo": "Permite procurar um assunto pelo nome e encontrar os itens, tabelas ou figuras correspondentes.", "quadro": null, "pergunta": "Como localizar rapidamente o volume útil da caixa coletora?", "resposta": "Procurar o termo no índice e seguir a referência a 5.1.6.7; a entrada está na página 74."}];
